INSERT INTO public.topics (id, title, slug, usmle_step, "order", section, is_free_demo, mcq_count, case_count)
INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, difficulty, "order", type) VALUES
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 28-year-old woman presents with 6 months of fatigue, exertional dyspnea, and heavy menstrual bleeding. Examination shows pale conjunctivae, spoon-shaped nails, and a smooth tongue. Labs: hemoglobin 9.2 g/dL, MCV 72 fL, ferritin 8 ng/mL, total iron-binding capacity elevated, reticulocyte count low. Peripheral smear shows microcytic hypochromic red cells. What is the most appropriate next step in management?', '["Intravenous iron infusion as first-line therapy", "Red blood cell transfusion to rapidly correct the anemia", "Oral ferrous sulfate with evaluation for the source of blood loss", "Intramuscular vitamin B12 injections", "Oral folic acid supplementation alone"]'::jsonb, 2, 'This patient has iron deficiency anemia from chronic menstrual blood loss, confirmed by microcytic hypochromic anemia with low ferritin and high TIBC. Oral ferrous sulfate is first-line therapy for iron deficiency in a hemodynamically stable patient, and the underlying source of blood loss must be evaluated. Intravenous iron is reserved for oral iron intolerance, malabsorption, or severe symptomatic anemia. Transfusion is unnecessary without hemodynamic instability or severe symptoms. Vitamin B12 and folic acid treat megaloblastic anemia, not iron deficiency, and folate alone would not correct the iron deficit or address the bleeding source.', 'Medium', 1, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 65-year-old man presents with 3 weeks of black tarry stools, fatigue, and lightheadedness. He takes no anticoagulants. Labs: hemoglobin 8.5 g/dL, MCV 70 fL, ferritin 10 ng/mL, stool guaiac positive. He is hemodynamically stable. What is the best initial diagnostic test?', '["Colonoscopy", "Upper endoscopy", "CT abdomen with contrast", "Repeat complete blood count in 1 week", "Iron studies alone without endoscopy"]'::jsonb, 0, 'Melena with iron deficiency anemia in an older adult mandates evaluation for gastrointestinal malignancy, and colonoscopy is the best initial test because colorectal cancer is the most common cause of occult lower GI blood loss in this age group. Upper endoscopy evaluates the upper tract but melena can arise from either, and guidelines prioritize colonoscopy first when iron deficiency is present. CT abdomen lacks sensitivity for mucosal lesions. Repeating the CBC or ordering iron studies alone delays diagnosis of a potentially curable cancer. Bidirectional endoscopy is often ultimately needed, but colonoscopy is the single best initial step here.', 'Medium', 2, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 2-year-old boy is brought for poor growth and pallor. His diet consists mainly of whole cow''s milk, about 40 ounces daily, with little solid food. Labs: hemoglobin 10.0 g/dL, MCV 70 fL, ferritin 6 ng/mL. Peripheral smear shows microcytic hypochromic cells. What is the most likely cause of his anemia?', '["Beta-thalassemia trait", "Lead poisoning", "Celiac disease", "Chronic gastrointestinal blood loss", "Excessive cow''s milk consumption displacing iron-rich foods"]'::jsonb, 4, 'Excessive cow''s milk intake in toddlers causes iron deficiency anemia by two mechanisms: milk is poor in iron and displaces iron-rich foods from the diet, and cow''s milk protein can cause occult intestinal blood loss. The microcytic anemia with very low ferritin confirms iron deficiency. Beta-thalassemia trait causes microcytosis with normal ferritin and an elevated red cell count. Lead poisoning causes anemia with basophilic stippling and developmental delay. Celiac disease causes malabsorption with diarrhea and poor growth but would not be suggested by this dietary history alone. Chronic GI blood loss is possible but the dietary pattern is the classic driver here.', 'Easy', 3, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 68-year-old woman who has followed a strict vegan diet for 20 years presents with 3 months of numbness and tingling in her hands and feet, difficulty walking, and fatigue. Examination shows loss of vibration sense and proprioception in the lower extremities, brisk reflexes, and a positive Romberg sign. Labs: hemoglobin 9.8 g/dL, MCV 110 fL, hypersegmented neutrophils on smear, vitamin B12 90 pg/mL, folate normal. What is the most likely diagnosis?', '["Folate deficiency", "Vitamin B12 deficiency with subacute combined degeneration", "Iron deficiency anemia", "Multiple sclerosis", "Lead poisoning"]'::jsonb, 1, 'Vitamin B12 deficiency causes megaloblastic anemia with hypersegmented neutrophils plus dorsal column and corticospinal tract degeneration, known as subacute combined degeneration, producing loss of vibration and proprioception with upper motor neuron signs. A long-standing vegan diet is a classic risk factor because B12 comes only from animal products. Folate deficiency causes identical hematologic findings but spares the nervous system, and folate is normal here. Iron deficiency causes microcytic anemia. Multiple sclerosis causes demyelination but not megaloblastic anemia. Lead poisoning causes microcytic anemia with basophilic stippling, not dorsal column disease.', 'Medium', 4, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old man presents 6 months after total gastrectomy for gastric cancer with fatigue, sore tongue, and paresthesias. Labs: hemoglobin 9.5 g/dL, MCV 112 fL, vitamin B12 120 pg/mL, methylmalonic acid elevated, homocysteine elevated. Peripheral smear shows hypersegmented neutrophils. What is the best initial treatment?', '["Oral folic acid", "Oral iron supplementation", "Red blood cell transfusion", "Intramuscular cyanocobalamin", "Oral vitamin B12 alone"]'::jsonb, 3, 'After total gastrectomy the patient lacks intrinsic factor, so dietary B12 cannot be absorbed, and the elevated methylmalonic acid confirms true B12 deficiency with neurologic involvement. Intramuscular cyanocobalamin bypasses absorption and is the preferred initial treatment when neurologic symptoms are present, ensuring rapid repletion. Oral folic acid would correct the anemia but worsen neurologic damage by masking the deficiency. Oral iron treats iron deficiency, not megaloblastic anemia. Transfusion is reserved for severe symptomatic anemia or hemodynamic instability. High-dose oral B12 can work in mild deficiency but parenteral therapy is standard with neurologic findings.', 'Medium', 5, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 40-year-old woman with pernicious anemia confirmed by positive anti-intrinsic factor antibodies presents with fatigue and a hemoglobin of 9.0 g/dL, MCV 114 fL, vitamin B12 100 pg/mL, and normal folate. She asks about long-term therapy. What is the most appropriate management?', '["Folic acid alone", "Oral iron supplementation", "Lifelong parenteral vitamin B12 replacement", "Red blood cell transfusion", "Dietary modification alone"]'::jsonb, 2, 'Pernicious anemia is autoimmune destruction of gastric parietal cells with loss of intrinsic factor, causing permanent B12 malabsorption that requires lifelong parenteral B12 replacement. Folic acid alone is dangerous because it corrects the anemia while allowing irreversible neurologic damage to progress. Oral iron does not address B12 deficiency. Transfusion is only for severe symptomatic anemia and does not treat the underlying deficiency. Dietary modification cannot overcome the absence of intrinsic factor, since even adequate dietary B12 cannot be absorbed. Lifelong intramuscular cyanocobalamin, typically monthly after loading doses, is the definitive therapy.', 'Easy', 6, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 26-year-old woman at 10 weeks of gestation presents for prenatal care. Labs show hemoglobin 10.2 g/dL, MCV 108 fL, vitamin B12 normal, serum folate low, and hypersegmented neutrophils. She has had poor oral intake due to nausea. What is the most appropriate management?', '["Folic acid supplementation", "Intramuscular vitamin B12 injections", "Oral iron supplementation alone", "Methotrexate therapy", "Red blood cell transfusion"]'::jsonb, 0, 'This patient has folate deficiency causing megaloblastic anemia in pregnancy, with low serum folate, normal B12, and hypersegmented neutrophils. Folic acid supplementation corrects the anemia and is essential in pregnancy to prevent neural tube defects. Vitamin B12 is normal, so injections are unnecessary, and giving folate without B12 would be safe here but B12 therapy alone would not fix the folate deficit. Oral iron treats iron deficiency anemia, which is microcytic rather than macrocytic. Methotrexate is a folate antagonist and is contraindicated in pregnancy. Transfusion is reserved for severe symptomatic anemia.', 'Easy', 7, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 58-year-old man with chronic alcohol use presents with fatigue and pallor. Labs: hemoglobin 9.6 g/dL, MCV 106 fL, vitamin B12 450 pg/mL, serum folate 1.8 ng/mL, methylmalonic acid normal, homocysteine elevated, hypersegmented neutrophils on smear. What is the most likely diagnosis?', '["Vitamin B12 deficiency", "Iron deficiency anemia", "Aplastic anemia", "Myelodysplastic syndrome", "Folate deficiency"]'::jsonb, 4, 'Folate deficiency from poor dietary intake and alcohol use causes megaloblastic anemia with macrocytosis and hypersegmented neutrophils. The normal B12 level and normal methylmalonic acid exclude B12 deficiency, since methylmalonic acid rises only in B12 deficiency, while homocysteine rises in both. Iron deficiency produces microcytic anemia with low ferritin, not macrocytosis. Aplastic anemia causes pancytopenia with a hypocellular marrow and normal MCV. Myelodysplastic syndrome causes macrocytic anemia in older adults but would show dysplastic cells and cytopenias, and the low folate with alcohol history makes folate deficiency the unifying diagnosis.', 'Medium', 8, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 62-year-old woman with rheumatoid arthritis on methotrexate for 5 years presents with fatigue. Labs: hemoglobin 9.8 g/dL, MCV 108 fL, vitamin B12 normal, folate low, hypersegmented neutrophils. What is the most likely cause of her anemia?', '["Iron deficiency anemia", "Methotrexate-induced folate deficiency", "Vitamin B12 deficiency", "Hemolytic anemia", "Aplastic anemia"]'::jsonb, 1, 'Methotrexate is a dihydrofolate reductase inhibitor that impairs folate metabolism, causing megaloblastic anemia with macrocytosis and hypersegmented neutrophils despite a normal B12 level. This is a classic drug-induced folate deficiency. Iron deficiency produces microcytic anemia with low ferritin. Vitamin B12 deficiency would show a low B12 level and elevated methylmalonic acid. Hemolytic anemia presents with reticulocytosis, elevated LDH, low haptoglobin, and indirect hyperbilirubinemia, none of which are described. Aplastic anemia causes pancytopenia with a hypocellular marrow, not isolated macrocytic anemia.', 'Medium', 9, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 60-year-old woman with long-standing rheumatoid arthritis presents with fatigue. Labs: hemoglobin 10.5 g/dL, MCV 82 fL, serum iron low, total iron-binding capacity low, ferritin 180 ng/mL, reticulocyte count low. What is the most likely diagnosis?', '["Iron deficiency anemia", "Vitamin B12 deficiency", "Beta-thalassemia trait", "Anemia of chronic inflammation", "Hemolytic anemia"]'::jsonb, 3, 'Anemia of chronic inflammation from rheumatoid arthritis is characterized by normocytic anemia with low serum iron, low TIBC, and normal or elevated ferritin, reflecting iron sequestration mediated by hepcidin. Iron deficiency anemia instead shows low ferritin with high TIBC. Vitamin B12 deficiency causes macrocytic anemia with hypersegmented neutrophils. Beta-thalassemia trait causes microcytosis with an elevated red cell count and normal ferritin. Hemolytic anemia presents with reticulocytosis, elevated LDH, low haptoglobin, and indirect hyperbilirubinemia. The inflammatory disease plus this iron pattern makes anemia of chronic inflammation the diagnosis.', 'Medium', 10, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 70-year-old man with chronic kidney disease stage 4 presents with fatigue and exertional dyspnea. Labs: hemoglobin 9.8 g/dL, MCV 86 fL, ferritin 90 ng/mL, transferrin saturation 18%, erythropoietin level low. What is the most appropriate treatment?', '["Erythropoiesis-stimulating agent with iron supplementation", "Red blood cell transfusion", "Oral iron alone", "Intramuscular vitamin B12", "Folic acid supplementation"]'::jsonb, 0, 'Anemia of chronic kidney disease results from inadequate erythropoietin production by the failing kidneys, and treatment is an erythropoiesis-stimulating agent such as epoetin alfa combined with iron repletion, since iron deficiency frequently coexists and limits the response. Transfusion is reserved for severe symptomatic anemia or acute blood loss and carries risks of alloimmunization and volume overload. Oral iron alone will not correct the erythropoietin deficit. Vitamin B12 and folic acid treat megaloblastic anemia, which is not present here given the normocytic indices and the low erythropoietin level.', 'Medium', 11, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old man with chronic hepatitis C infection has hemoglobin 10.8 g/dL, MCV 84 fL, serum iron low, total iron-binding capacity low, and ferritin 320 ng/mL. Which finding best distinguishes his anemia from iron deficiency anemia?', '["Low serum ferritin", "Elevated total iron-binding capacity", "Elevated ferritin with low total iron-binding capacity", "Elevated reticulocyte count", "Positive direct Coombs test"]'::jsonb, 2, 'Anemia of chronic inflammation is distinguished from iron deficiency anemia by ferritin and TIBC: ferritin is normal or elevated because it is an acute-phase reactant and iron is sequestered in macrophages, while TIBC is low. In true iron deficiency, ferritin is low and TIBC is elevated as the body upregulates transferrin to capture scarce iron. A low ferritin points toward iron deficiency, not chronic inflammation. An elevated TIBC is seen in iron deficiency. The reticulocyte count is low in both conditions. A positive direct Coombs test indicates autoimmune hemolytic anemia, a different mechanism entirely.', 'Hard', 12, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 45-year-old woman with systemic lupus erythematosus presents with fatigue, jaundice, and dark urine. Labs: hemoglobin 7.5 g/dL, reticulocyte count 12%, LDH 900 U/L, haptoglobin undetectable, indirect bilirubin 4.2 mg/dL. Peripheral smear shows spherocytes. Direct Coombs test is positive for IgG. What is the most likely diagnosis?', '["Cold agglutinin disease", "Warm autoimmune hemolytic anemia", "Glucose-6-phosphate dehydrogenase deficiency", "Thrombotic thrombocytopenic purpura", "Hereditary spherocytosis"]'::jsonb, 1, 'Warm autoimmune hemolytic anemia is an IgG-mediated extravascular hemolysis, typically associated with SLE or lymphoma, with a positive direct Coombs test for IgG, spherocytes, reticulocytosis, elevated LDH, low haptoglobin, and indirect hyperbilirubinemia. Cold agglutinin disease is IgM-mediated, Coombs positive for complement C3, and triggered by cold exposure. G6PD deficiency causes episodic hemolysis after oxidant stress with bite cells and Heinz bodies, not a positive Coombs test. Thrombotic thrombocytopenic purpura causes microangiopathic hemolysis with schistocytes, thrombocytopenia, and neurologic findings. Hereditary spherocytosis has a negative Coombs test and a family history.', 'Medium', 13, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 38-year-old woman with warm autoimmune hemolytic anemia presents with hemoglobin 6.8 g/dL, dyspnea at rest, and chest discomfort. Reticulocytes are elevated, LDH is high, and haptoglobin is undetectable. What is the most appropriate initial treatment?', '["Splenectomy", "Rituximab", "Transfusion alone", "Plasmapheresis", "High-dose corticosteroids"]'::jsonb, 4, 'High-dose corticosteroids such as prednisone are first-line therapy for warm autoimmune hemolytic anemia because they suppress autoantibody production and reduce macrophage-mediated destruction of IgG-coated red cells. Transfusion alone does not stop hemolysis and transfused cells are also destroyed, though transfusion is given concurrently for severe symptomatic anemia. Splenectomy is second-line for refractory disease. Rituximab is reserved for steroid-refractory cases. Plasmapheresis is not effective for warm AIHA because the antibody is IgG and the hemolysis is extravascular; it is used in thrombotic thrombocytopenic purpura instead.', 'Medium', 14, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 60-year-old man recovering from Mycoplasma pneumonia develops acrocyanosis of his fingers and ears on cold exposure, fatigue, and jaundice. Labs: hemoglobin 9.0 g/dL, reticulocyte count elevated, LDH elevated, haptoglobin low, cold agglutinin titer 1:1024, direct Coombs test positive for complement C3. What is the most likely diagnosis?', '["Cold agglutinin disease", "Warm autoimmune hemolytic anemia", "Paroxysmal nocturnal hemoglobinuria", "Disseminated intravascular coagulation", "Sickle cell disease"]'::jsonb, 0, 'Cold agglutinin disease is an IgM-mediated hemolytic anemia in which cold-reactive antibodies agglutinate red cells in cooler extremities, causing acrocyanosis and complement-mediated hemolysis; the direct Coombs test is positive for C3 rather than IgG. It commonly follows Mycoplasma pneumonia or infectious mononucleosis. Warm autoimmune hemolytic anemia is IgG-mediated, Coombs positive for IgG, and lacks cold-induced acrocyanosis. Paroxysmal nocturnal hemoglobinuria causes complement-mediated hemolysis with hemoglobinuria and thrombosis but no cold agglutinins. Disseminated intravascular coagulation causes schistocytes and coagulopathy. Sickle cell disease causes vaso-occlusive pain and sickled cells on smear.', 'Medium', 15, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 25-year-old man of African descent presents with dark urine, jaundice, and fatigue 2 days after starting trimethoprim-sulfamethoxazole for a urinary tract infection. Labs: hemoglobin 8.0 g/dL, reticulocyte count elevated, LDH elevated, haptoglobin low, indirect bilirubin elevated. Peripheral smear shows bite cells and Heinz bodies. What is the most likely diagnosis?', '["Sickle cell disease", "Beta-thalassemia major", "Autoimmune hemolytic anemia", "Glucose-6-phosphate dehydrogenase deficiency", "Hereditary spherocytosis"]'::jsonb, 3, 'Glucose-6-phosphate dehydrogenase deficiency is an X-linked disorder in which oxidant stress from drugs such as trimethoprim-sulfamethoxazole, infections, or fava beans precipitates acute hemolysis, with bite cells and Heinz bodies on smear from oxidatively damaged hemoglobin. Sickle cell disease causes vaso-occlusive crises and sickled cells, not bite cells. Beta-thalassemia major presents in early childhood with severe microcytic anemia and transfusion dependence. Autoimmune hemolytic anemia has a positive direct Coombs test, which is absent here. Hereditary spherocytosis shows spherocytes with a negative Coombs test and a family history of splenectomy or gallstones.', 'Medium', 16, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 30-year-old man with known glucose-6-phosphate dehydrogenase deficiency develops acute hemolysis with hemoglobin falling from 13 to 9 g/dL after a viral illness. He is hemodynamically stable with no signs of heart failure. What is the most appropriate management?', '["Start high-dose corticosteroids", "Discontinue any offending drug and provide supportive care", "Urgent splenectomy", "Immediate red blood cell transfusion", "Start hydroxyurea"]'::jsonb, 1, 'Acute hemolysis in G6PD deficiency is self-limited once the oxidant trigger is removed, so management is to discontinue any offending drug, treat the underlying infection, ensure hydration, and monitor hemoglobin, with transfusion only if anemia becomes severe or symptomatic. Corticosteroids have no role because the hemolysis is not immune-mediated. Splenectomy is not indicated in G6PD deficiency. Immediate transfusion is unnecessary in a stable patient and is reserved for severe symptomatic anemia. Hydroxyurea is used in sickle cell disease to raise fetal hemoglobin, not in G6PD deficiency.', 'Easy', 17, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 22-year-old man with glucose-6-phosphate dehydrogenase deficiency is traveling to a malaria-endemic region and asks about antimalarial prophylaxis. Which drug should he avoid because it can precipitate hemolysis?', '["Chloroquine", "Mefloquine", "Primaquine", "Artemether-lumefantrine", "Doxycycline"]'::jsonb, 2, 'Primaquine is a potent oxidant drug that precipitates acute hemolysis in G6PD deficiency and is contraindicated; it is also used for radical cure of Plasmodium vivax, making G6PD testing mandatory before its use. Chloroquine, mefloquine, artemether-lumefantrine, and doxycycline are generally considered safe alternatives for malaria prophylaxis or treatment in G6PD-deficient patients, though all drug choices should be reviewed carefully. The key teaching point is that primaquine and other strong oxidants such as dapsone, nitrofurantoin, and rasburicase must be avoided in these patients.', 'Medium', 18, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 12-year-old boy with sickle cell disease presents with 2 days of severe pain in his arms, legs, and back, low-grade fever, and dehydration. Labs: hemoglobin 6.5 g/dL, reticulocyte count elevated, LDH elevated. Examination shows tender long bones without swelling or erythema. What is the most appropriate next step in management?', '["Intravenous hydration and analgesia", "Immediate red blood cell transfusion", "Antibiotics alone without analgesia", "Start hydroxyurea immediately", "Splenectomy"]'::jsonb, 0, 'This is a vaso-occlusive crisis, the most common complication of sickle cell disease, caused by sickled red cells obstructing microvasculature and producing ischemic bone pain. Management is supportive: intravenous hydration to reduce sickling, adequate analgesia, oxygen if hypoxic, and monitoring for complications such as acute chest syndrome. Transfusion is reserved for specific indications such as acute chest syndrome, stroke, or severe symptomatic anemia, not uncomplicated pain crises. Antibiotics are added only if infection is suspected. Hydroxyurea is long-term preventive therapy, not acute treatment. Splenectomy has no role in vaso-occlusive crisis.', 'Easy', 19, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 20-year-old man with sickle cell disease presents with chest pain, fever of 38.8 C, dyspnea, and oxygen saturation of 89% on room air. Chest radiograph shows a new right lower lobe infiltrate. Labs: hemoglobin 6.8 g/dL, leukocytosis. What is the most likely diagnosis?', '["Pulmonary embolism", "Bacterial pneumonia alone", "Acute asthma exacerbation", "Acute myocardial infarction", "Acute chest syndrome"]'::jsonb, 4, 'Acute chest syndrome is a life-threatening complication of sickle cell disease defined by fever, chest pain, hypoxia, and a new pulmonary infiltrate, caused by vaso-occlusion and infection in the lungs. It requires urgent management with oxygen, broad-spectrum antibiotics, analgesia, and often simple or exchange transfusion. Pulmonary embolism can mimic it but the fever and infiltrate with sickle cell disease favor acute chest syndrome. Bacterial pneumonia alone does not explain the degree of hypoxia and hemolysis in this context. Asthma does not cause a new infiltrate. Myocardial infarction is unlikely in a 20-year-old and would show ischemic ECG changes.', 'Medium', 20, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 6-year-old girl with sickle cell disease has had 4 vaso-occlusive crises in the past year requiring hospitalization. Her parents ask about long-term therapy to reduce the frequency of crises. Which medication is most appropriate?', '["Daily iron supplementation", "Hydroxyurea", "Daily aspirin", "Splenectomy", "Folic acid alone"]'::jsonb, 1, 'Hydroxyurea increases fetal hemoglobin production, which interferes with sickle hemoglobin polymerization and reduces the frequency of vaso-occlusive crises, acute chest syndrome, and transfusions; it is the standard disease-modifying therapy for children with recurrent crises. Iron supplementation is not indicated and iron overload is a concern in transfused patients. Daily aspirin does not prevent sickling. Splenectomy is reserved for recurrent splenic sequestration, not vaso-occlusive crises. Folic acid is given routinely because of chronic hemolysis, but it does not reduce crisis frequency.', 'Medium', 21, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 2-year-old girl of Mediterranean descent presents with severe anemia, poor growth, and hepatosplenomegaly. Labs: hemoglobin 6.0 g/dL, MCV 62 fL, markedly elevated hemoglobin F, absent hemoglobin A. She has required transfusions since infancy. What is the most likely diagnosis?', '["Iron deficiency anemia", "Sickle cell disease", "Alpha-thalassemia trait", "Beta-thalassemia major", "Aplastic anemia"]'::jsonb, 3, 'Beta-thalassemia major results from absent beta-globin synthesis, producing severe microcytic anemia presenting in infancy, marked elevation of hemoglobin F, hepatosplenomegaly from extramedullary hematopoiesis, and lifelong transfusion dependence with iron overload as a major complication. Iron deficiency anemia shows low ferritin and responds to iron, not this pattern of absent hemoglobin A. Sickle cell disease presents with vaso-occlusive pain and hemoglobin S on electrophoresis. Alpha-thalassemia trait causes only mild asymptomatic microcytosis. Aplastic anemia causes pancytopenia with a hypocellular marrow, not isolated severe microcytic anemia with elevated hemoglobin F.', 'Medium', 22, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 30-year-old woman of Mediterranean descent is found to have hemoglobin 11.0 g/dL, MCV 68 fL, red blood cell count 5.8 million, RDW normal, ferritin 90 ng/mL, and hemoglobin A2 of 5.8%. She is asymptomatic. What is the most likely diagnosis?', '["Iron deficiency anemia", "Lead poisoning", "Beta-thalassemia trait", "Anemia of chronic disease", "Sideroblastic anemia"]'::jsonb, 2, 'Beta-thalassemia trait is characterized by mild microcytic anemia with a disproportionately high red blood cell count, normal RDW, normal ferritin, and elevated hemoglobin A2 above 3.5%, reflecting reduced beta-chain synthesis with compensatory delta-chain production. Iron deficiency anemia shows low ferritin, high RDW, and a low red cell count. Lead poisoning causes microcytic anemia with basophilic stippling and often developmental or neurologic symptoms. Anemia of chronic disease is normocytic with low iron and high ferritin. Sideroblastic anemia shows ring sideroblasts on marrow and often a dimorphic smear.', 'Hard', 23, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A newborn of Southeast Asian descent is delivered with severe hydrops fetalis, generalized edema, and hepatosplenomegaly, and dies shortly after birth. Hemoglobin electrophoresis shows predominantly hemoglobin Bart''s with no hemoglobin A or F. What is the most likely diagnosis?', '["Alpha-thalassemia major", "Beta-thalassemia major", "Sickle cell disease", "Glucose-6-phosphate dehydrogenase deficiency", "Hereditary spherocytosis"]'::jsonb, 0, 'Alpha-thalassemia major, or hemoglobin Bart''s hydrops fetalis, results from deletion of all four alpha-globin genes, so no alpha chains are produced and only gamma tetramers (hemoglobin Bart''s) form; the fetus develops severe anemia, hydrops, and usually dies in utero or shortly after birth. Beta-thalassemia major presents after infancy when fetal hemoglobin switching occurs, not at birth. Sickle cell disease presents with vaso-occlusive crises and hemoglobin S. G6PD deficiency causes episodic hemolysis after oxidant exposure. Hereditary spherocytosis presents with hemolysis, spherocytes, and splenomegaly, not hydrops with hemoglobin Bart''s.', 'Hard', 24, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 30-year-old man presents with 2 months of fatigue, easy bruising, and recurrent nosebleeds. Labs: hemoglobin 8.0 g/dL, white blood cell count 2,000 per microliter, platelets 30,000 per microliter, reticulocyte count low. He took chloramphenicol 3 months ago. Bone marrow biopsy shows a markedly hypocellular marrow with no blasts or dysplasia. What is the most likely diagnosis?', '["Acute leukemia", "Aplastic anemia", "Myelodysplastic syndrome", "Vitamin B12 deficiency", "Hypersplenism"]'::jsonb, 1, 'Aplastic anemia is a failure of hematopoietic stem cells causing pancytopenia with a hypocellular marrow, often triggered by drugs such as chloramphenicol, benzene, or idiosyncratic drug reactions. Acute leukemia would show blasts in the marrow or peripheral blood. Myelodysplastic syndrome shows dysplastic cells and a hypercellular or normocellular marrow in an older patient. Vitamin B12 deficiency causes macrocytic anemia with hypersegmented neutrophils, not pancytopenia with an empty marrow. Hypersplenism causes cytopenias with splenomegaly and a cellular marrow, not a hypocellular one.', 'Medium', 25, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 22-year-old man is diagnosed with severe aplastic anemia with an absolute neutrophil count of 300 per microliter and platelets of 15,000 per microliter. He has a fully HLA-matched sibling donor. What is the best definitive treatment?', '["Red blood cell and platelet transfusion alone", "High-dose corticosteroids", "Splenectomy", "Antithymocyte globulin alone", "Allogeneic hematopoietic stem cell transplantation"]'::jsonb, 4, 'Allogeneic hematopoietic stem cell transplantation from a matched sibling donor is the definitive, potentially curative treatment for severe aplastic anemia in young patients, replacing the failed marrow with healthy donor stem cells. Transfusion alone is supportive and does not restore marrow function. Corticosteroids are not effective for aplastic anemia. Splenectomy has no role. Antithymocyte globulin combined with cyclosporine is the standard immunosuppressive therapy for patients without a matched donor or older patients, but transplantation is preferred when a matched sibling donor is available in a young patient.', 'Medium', 26, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 45-year-old woman with aplastic anemia is found to have a paroxysmal nocturnal hemoglobinuria clone on flow cytometry. She has no matched sibling donor. What is the most appropriate next step in management?', '["Oral iron supplementation", "Intramuscular vitamin B12", "Splenectomy", "Antithymocyte globulin plus cyclosporine", "Hydroxyurea"]'::jsonb, 3, 'Aplastic anemia with a paroxysmal nocturnal hemoglobinuria clone is managed with immunosuppressive therapy using antithymocyte globulin plus cyclosporine when no matched sibling donor is available, since the disease is immune-mediated destruction of hematopoietic stem cells. Oral iron and vitamin B12 do not address marrow failure. Splenectomy has no role in aplastic anemia. Hydroxyurea is used in sickle cell disease to raise fetal hemoglobin and does not treat aplastic anemia. Eculizumab is used for hemolytic paroxysmal nocturnal hemoglobinuria, but the dominant problem here is marrow failure, which requires immunosuppression.', 'Hard', 27, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 72-year-old woman presents with fatigue and pallor. Labs: hemoglobin 8.5 g/dL, MCV 118 fL, white blood cell count 3,000 per microliter, platelets 90,000 per microliter, reticulocyte count low, vitamin B12 110 pg/mL, folate normal. Peripheral smear shows hypersegmented neutrophils. What is the most likely cause of her pancytopenia?', '["Vitamin B12 deficiency", "Iron deficiency anemia", "Aplastic anemia", "Myelodysplastic syndrome", "Hemolytic anemia"]'::jsonb, 0, 'Severe vitamin B12 deficiency causes ineffective erythropoiesis with intramedullary death of hematopoietic precursors, producing pancytopenia with macrocytosis and hypersegmented neutrophils; the low B12 level and normal folate confirm the diagnosis and distinguish it from folate deficiency. Iron deficiency causes microcytic anemia without leukopenia or thrombocytopenia. Aplastic anemia causes pancytopenia but with a hypocellular marrow and normal MCV, not macrocytosis with hypersegmented neutrophils. Myelodysplastic syndrome can cause pancytopenia with macrocytosis but would show dysplasia and normal B12 levels. Hemolytic anemia causes reticulocytosis, not a low reticulocyte count.', 'Medium', 28, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 58-year-old man presents with fatigue, easy bruising, and recurrent infections over 3 months. Labs: hemoglobin 9.0 g/dL, MCV 100 fL, white blood cell count 2,500 per microliter, platelets 80,000 per microliter, vitamin B12 and folate normal, reticulocyte count low. What is the best initial diagnostic test?', '["Repeat complete blood count in 4 weeks", "Iron studies", "Bone marrow biopsy", "Direct Coombs test", "CT scan of the abdomen"]'::jsonb, 2, 'Unexplained pancytopenia with a low reticulocyte count and normal B12 and folate requires bone marrow biopsy to evaluate for aplastic anemia, myelodysplastic syndrome, leukemia, or marrow infiltration. Repeating the CBC delays diagnosis of a potentially serious marrow disorder. Iron studies evaluate iron deficiency, which does not cause pancytopenia. A direct Coombs test evaluates autoimmune hemolysis, which would show reticulocytosis rather than a low reticulocyte count. CT of the abdomen may show splenomegaly but does not establish the cause of pancytopenia; marrow examination is the definitive next step.', 'Medium', 29, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 70-year-old man presents with fatigue and is found to have hemoglobin 10.0 g/dL, MCV 104 fL, white blood cell count 3,200 per microliter, platelets 110,000 per microliter, vitamin B12 600 pg/mL, folate 12 ng/mL. Peripheral smear shows hypersegmented neutrophils and pseudo-Pelger-Huet cells. Bone marrow shows ring sideroblasts and dysplastic erythroid precursors. What is the most likely diagnosis?', '["Vitamin B12 deficiency", "Myelodysplastic syndrome", "Aplastic anemia", "Iron deficiency anemia", "Hemolytic anemia"]'::jsonb, 1, 'Myelodysplastic syndrome is a clonal disorder of ineffective hematopoiesis in older adults causing cytopenias with macrocytosis, dysplastic cells such as pseudo-Pelger-Huet neutrophils, and ring sideroblasts on marrow examination, with normal B12 and folate levels. Vitamin B12 deficiency also causes hypersegmented neutrophils but the B12 level is normal here and dysplasia with ring sideroblasts points to MDS. Aplastic anemia shows a hypocellular marrow without dysplasia. Iron deficiency causes microcytic anemia. Hemolytic anemia presents with reticulocytosis, elevated LDH, and low haptoglobin rather than pancytopenia with dysplasia.', 'Hard', 30, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 62-year-old man presents with 3 weeks of fatigue, gum bleeding, and easy bruising. His white blood cell count is 2.1 x 10^9/L, hemoglobin 8.2 g/dL, and platelets 28 x 10^9/L. The peripheral smear shows blasts with Auer rods. Fibrinogen is low and D-dimer is markedly elevated. Cytogenetics reveal t(15;17). What is the most appropriate next step in management?', '["Start hydroxyurea alone for cytoreduction", "Start all-trans retinoic acid plus arsenic trioxide immediately", "Start imatinib", "Start rituximab", "Observe and repeat the complete blood count in 1 week"]'::jsonb, 1, 'This is acute promyelocytic leukemia, the t(15;17) PML-RARA subtype of AML, which presents with pancytopenia, Auer rods, and disseminated intravascular coagulation. All-trans retinoic acid plus arsenic trioxide is the standard treatment for low- and intermediate-risk APL and must be started immediately because of the high risk of fatal hemorrhage. Hydroxyurea alone is only cytoreduction and does not treat the leukemia. Imatinib is a BCR-ABL tyrosine kinase inhibitor used for chronic myeloid leukemia. Rituximab targets CD20-positive B-cell lymphomas. Observation is dangerous because APL-associated coagulopathy can cause fatal bleeding within hours.', 'Hard', 31, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old woman presents with fever, fatigue, and petechiae for 2 weeks. Her white blood cell count is 42 x 10^9/L with 60% blasts, hemoglobin 7.8 g/dL, and platelets 35 x 10^9/L. Bone marrow biopsy shows more than 20% myeloblasts that stain positive for myeloperoxidase. What is the most likely diagnosis?', '["Acute lymphoblastic leukemia", "Chronic myeloid leukemia", "Acute myeloid leukemia", "Myelodysplastic syndrome", "Aplastic anemia"]'::jsonb, 2, 'More than 20% blasts in the marrow with myeloid markers such as myeloperoxidase establishes acute myeloid leukemia, which typically presents with pancytopenia, fever, and bleeding from marrow failure. Acute lymphoblastic leukemia has lymphoid blasts that are TdT-positive and myeloperoxidase-negative, and it most often affects children. Chronic myeloid leukemia in chronic phase shows a full spectrum of maturing granulocytes with few blasts. Myelodysplastic syndrome has fewer than 20% blasts with dysplastic features. Aplastic anemia has a hypocellular marrow without increased blasts.', 'Medium', 32, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 48-year-old man is newly diagnosed with acute myeloid leukemia with normal cytogenetics. He is fit, with no significant comorbidities and a good performance status. What is the best initial treatment?', '["Cytarabine plus daunorubicin (7+3) induction chemotherapy", "Imatinib monotherapy", "All-trans retinoic acid plus arsenic trioxide", "Hydroxyurea alone", "Palliative care only"]'::jsonb, 0, 'Standard induction therapy for a fit younger adult with AML is cytarabine plus an anthracycline, the 7+3 regimen, which aims for complete remission followed by consolidation. Imatinib is a BCR-ABL inhibitor used for chronic myeloid leukemia and has no role in AML. All-trans retinoic acid plus arsenic trioxide is specific treatment for acute promyelocytic leukemia, the t(15;17) subtype. Hydroxyurea provides only temporary cytoreduction and is not definitive therapy. Palliative care alone is inappropriate for a fit patient with a potentially curable leukemia.', 'Medium', 33, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 4-year-old boy presents with fever, bone pain, pallor, and lymphadenopathy for 3 weeks. Examination shows hepatosplenomegaly. His white blood cell count is 8 x 10^9/L, hemoglobin 7.5 g/dL, and platelets 60 x 10^9/L. The peripheral smear shows lymphoblasts that are positive for terminal deoxynucleotidyl transferase (TdT). What is the most likely diagnosis?', '["Acute myeloid leukemia", "Chronic lymphocytic leukemia", "Aplastic anemia", "Acute lymphoblastic leukemia", "Juvenile myelomonocytic leukemia"]'::jsonb, 3, 'Acute lymphoblastic leukemia is the most common childhood cancer, peaking at ages 2 to 5 years, and presents with fever, bone pain, pallor, lymphadenopathy, and hepatosplenomegaly; the lymphoblasts are TdT-positive and often CD10-positive. Acute myeloid leukemia has myeloid blasts that are myeloperoxidase-positive and is less common in young children. Chronic lymphocytic leukemia is a disease of older adults with mature lymphocytes and smudge cells. Aplastic anemia causes pancytopenia with a hypocellular marrow and no blasts. Juvenile myelomonocytic leukemia presents with monocytosis, splenomegaly, and a distinct RAS-pathway immunophenotype.', 'Medium', 34, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 6-year-old girl is newly diagnosed with B-cell acute lymphoblastic leukemia. Cerebrospinal fluid examination shows no blasts, and imaging shows no central nervous system involvement. What is the most appropriate next step in management?', '["Imatinib alone", "All-trans retinoic acid plus arsenic trioxide", "Splenectomy", "Observation", "Multiagent chemotherapy with intrathecal central nervous system prophylaxis"]'::jsonb, 4, 'Childhood B-ALL is treated with multiagent chemotherapy in phases of induction, consolidation, and maintenance, plus central nervous system prophylaxis with intrathecal methotrexate, because the central nervous system is a sanctuary site; cure rates now exceed 90%. Imatinib is added only for Philadelphia chromosome-positive ALL, not standard-risk disease. All-trans retinoic acid plus arsenic trioxide is treatment for acute promyelocytic leukemia. Splenectomy has no role in ALL therapy. Observation is fatal because untreated ALL progresses rapidly with marrow failure, infection, and bleeding.', 'Medium', 35, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 7-year-old boy is on day 3 of induction chemotherapy for acute lymphoblastic leukemia. He develops hyperkalemia, hyperphosphatemia, hypocalcemia, hyperuricemia, and a rising creatinine. What is the most appropriate management?', '["Stop all intravenous fluids", "Aggressive intravenous hydration plus rasburicase", "Start dialysis immediately without other measures", "Give calcium gluconate alone", "Continue chemotherapy unchanged"]'::jsonb, 1, 'This is tumor lysis syndrome, caused by rapid destruction of malignant cells releasing potassium, phosphate, and nucleic acids, with secondary hypocalcemia, hyperuricemia, and acute kidney injury. Aggressive intravenous hydration plus rasburicase, which converts uric acid to soluble allantoin, is the standard treatment; allopurinol is an alternative that only prevents new uric acid formation. Stopping fluids worsens kidney injury and uric acid precipitation. Dialysis is reserved for refractory hyperkalemia, acidosis, or fluid overload despite medical therapy. Calcium gluconate treats only symptomatic hypocalcemia, and asymptomatic hypocalcemia is not corrected because it risks calcium phosphate precipitation.', 'Hard', 36, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 52-year-old man presents with fatigue and left upper quadrant fullness for 2 months. Examination shows marked splenomegaly. His white blood cell count is 180 x 10^9/L with a full spectrum of maturing myeloid cells and basophilia, hemoglobin 11 g/dL, and platelets 600 x 10^9/L. What is the most likely diagnosis?', '["Acute myeloid leukemia", "Acute lymphoblastic leukemia", "Chronic lymphocytic leukemia", "Chronic myeloid leukemia", "Essential thrombocythemia"]'::jsonb, 3, 'Chronic myeloid leukemia in chronic phase presents with marked leukocytosis showing all stages of myeloid maturation, basophilia, a low leukocyte alkaline phosphatase score, splenomegaly, and fatigue, driven by the Philadelphia chromosome and BCR-ABL. Acute myeloid leukemia has more than 20% blasts with pancytopenia rather than a full maturation spectrum. Acute lymphoblastic leukemia has lymphoblasts and usually affects children. Chronic lymphocytic leukemia shows a mature lymphocytosis with smudge cells in older adults. Essential thrombocythemia causes isolated thrombocytosis without leukocytosis or marked splenomegaly.', 'Medium', 37, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 50-year-old man is newly diagnosed with chronic-phase chronic myeloid leukemia and is positive for BCR-ABL. What is the best initial treatment?', '["Imatinib, a tyrosine kinase inhibitor", "All-trans retinoic acid plus arsenic trioxide", "Hydroxyurea indefinitely", "Allogeneic stem cell transplant immediately", "Interferon alfa alone"]'::jsonb, 0, 'Tyrosine kinase inhibitors such as imatinib are first-line therapy for chronic-phase CML because they target the BCR-ABL fusion protein and produce deep, durable responses. All-trans retinoic acid plus arsenic trioxide is treatment for acute promyelocytic leukemia. Hydroxyurea is useful only as a temporary bridge to reduce very high white cell counts. Allogeneic transplant is reserved for tyrosine kinase inhibitor failure or advanced-phase disease because of its toxicity. Interferon alfa is historical therapy with inferior response rates and significant side effects.', 'Easy', 38, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 58-year-old man with chronic myeloid leukemia on imatinib presents with fever, bone pain, and fatigue. His white blood cell count is 90 x 10^9/L with 35% blasts, hemoglobin 8.0 g/dL, and platelets 40 x 10^9/L. What is the most likely explanation?', '["Drug-induced cytopenia", "New infection alone", "Transformation to aplastic anemia", "Imatinib-induced remission", "Blast crisis transformation"]'::jsonb, 4, 'A blast percentage of 20% or more in blood or marrow defines blast phase CML, an aggressive transformation resembling acute leukemia that requires urgent reassessment, a switch in tyrosine kinase inhibitor, and evaluation for stem cell transplant. Drug-induced cytopenia from imatinib causes low counts without a blast excess. Infection alone does not produce circulating blasts. Aplastic anemia has a hypocellular marrow without blasts. Remission would show normalization of blood counts and disappearance of blasts, the opposite of these findings. Management includes stopping the failing tyrosine kinase inhibitor, starting a second-generation agent or chemotherapy, and urgent transplant evaluation.', 'Hard', 39, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 68-year-old man is asymptomatic. A routine complete blood count shows a white blood cell count of 45 x 10^9/L with an absolute lymphocyte count of 38 x 10^9/L and smudge cells on the smear. Examination shows small cervical lymph nodes. What is the most likely diagnosis?', '["Acute lymphoblastic leukemia", "Chronic myeloid leukemia", "Chronic lymphocytic leukemia", "Hairy cell leukemia", "Mantle cell lymphoma"]'::jsonb, 2, 'Chronic lymphocytic leukemia is a disease of older adults characterized by a sustained absolute lymphocytosis greater than 5 x 10^9/L, mature-appearing lymphocytes, and fragile smudge cells on the smear; flow cytometry typically shows CD5- and CD23-positive B cells. Acute lymphoblastic leukemia has lymphoblasts and usually affects children. Chronic myeloid leukemia shows a granulocytic picture with basophilia and splenomegaly. Hairy cell leukemia causes pancytopenia with splenomegaly and hairy lymphocytes. Mantle cell lymphoma usually presents with bulky lymphadenopathy and carries t(11;14) with cyclin D1 overexpression.', 'Medium', 40, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 70-year-old man has chronic lymphocytic leukemia, Rai stage 0, with no symptoms, no cytopenias, and no bulky lymphadenopathy. What is the most appropriate management?', '["Watchful waiting with regular monitoring", "Immediate combination chemotherapy", "Imatinib", "Splenectomy", "Allogeneic stem cell transplant now"]'::jsonb, 0, 'Early-stage asymptomatic CLL is managed with watchful waiting because treatment does not improve survival in this setting, and therapy is started only for symptomatic or progressive disease such as B symptoms, cytopenias, bulky nodes, or a rapidly doubling lymphocyte count. Immediate chemotherapy exposes the patient to toxicity without benefit. Imatinib is a BCR-ABL inhibitor for chronic myeloid leukemia. Splenectomy is reserved for refractory autoimmune cytopenias or symptomatic splenomegaly. Allogeneic transplant is considered only in high-risk or refractory disease because of its substantial risks.', 'Medium', 41, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 72-year-old man with chronic lymphocytic leukemia develops rapidly enlarging lymph nodes, fever, weight loss, and a markedly elevated lactate dehydrogenase. What is the most concerning diagnosis?', '["Benign reactive lymph nodes", "Imatinib resistance", "Hemolytic anemia", "Richter transformation to diffuse large B-cell lymphoma", "Viral infection"]'::jsonb, 3, 'Rapid nodal growth with B symptoms and a very high LDH in a patient with CLL suggests Richter transformation to diffuse large B-cell lymphoma, an aggressive complication requiring biopsy and intensive therapy. Benign reactive nodes do not grow rapidly with a markedly elevated LDH. Imatinib is not a CLL therapy, so resistance is irrelevant. Autoimmune hemolytic anemia causes anemia and jaundice, not rapidly enlarging nodes. Viral infection is usually self-limited and does not produce this degree of LDH elevation with progressive nodal enlargement.', 'Hard', 42, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 28-year-old man presents with painless cervical lymphadenopathy, drenching night sweats, and weight loss. Lymph node biopsy shows Reed-Sternberg cells in a mixed cellularity background that stain positive for CD15 and CD30. What is the most likely diagnosis?', '["Non-Hodgkin lymphoma", "Hodgkin lymphoma", "Tuberculous lymphadenitis", "Sarcoidosis", "Metastatic carcinoma"]'::jsonb, 1, 'Reed-Sternberg cells that are CD15- and CD30-positive define Hodgkin lymphoma, which typically presents in young adults with painless lymphadenopathy and B symptoms and has a bimodal age distribution. Non-Hodgkin lymphoma lacks Reed-Sternberg cells and has a different immunophenotype. Tuberculous lymphadenitis shows caseating granulomas with acid-fast bacilli. Sarcoidosis shows noncaseating granulomas without Reed-Sternberg cells. Metastatic carcinoma shows malignant epithelial cells, not Reed-Sternberg cells. Staging with PET-CT and bone marrow assessment guides therapy, and the disease is highly curable. Tuberculous nodes often show caseation with positive cultures, sarcoid nodes show noncaseating granulomas with elevated ACE, and metastatic carcinoma cells express epithelial markers such as cytokeratins.', 'Medium', 43, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 25-year-old woman is diagnosed with stage IIA Hodgkin lymphoma without bulky disease. What is the most appropriate treatment?', '["Imatinib", "All-trans retinoic acid plus arsenic trioxide", "Splenectomy alone", "Observation", "ABVD chemotherapy with involved-site radiation"]'::jsonb, 4, 'Early-stage favorable Hodgkin lymphoma is treated with ABVD chemotherapy, often combined with involved-site radiation, which achieves cure rates above 90% after staging with PET-CT. Imatinib is a BCR-ABL inhibitor for chronic myeloid leukemia. All-trans retinoic acid plus arsenic trioxide is treatment for acute promyelocytic leukemia. Splenectomy is not a treatment for Hodgkin lymphoma. Observation is inappropriate because Hodgkin lymphoma is curable with therapy but fatal if untreated. Treatment is guided by stage and risk factors, with combined modality therapy for early favorable disease and ABVD alone or escalated BEACOPP for advanced disease. Cure rates exceed 90% in early-stage disease.', 'Medium', 44, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 65-year-old man with sepsis develops bleeding from intravenous sites and petechiae. His platelets are 45 x 10^9/L, prothrombin time and activated partial thromboplastin time are prolonged, fibrinogen is low, and D-dimer is markedly elevated. What is the most appropriate management?', '["Give heparin to all patients with this condition", "Give platelet transfusion alone without treating the cause", "Treat the underlying cause and replace blood products if bleeding", "Stop all antibiotics", "Give warfarin"]'::jsonb, 2, 'This is disseminated intravascular coagulation from sepsis, and the cornerstone of management is treating the underlying cause, in this case sepsis with antibiotics and source control, while replacing platelets, fibrinogen, and clotting factors when there is active bleeding. Heparin is used only in selected cases with thrombosis, not routinely in bleeding DIC. Platelet transfusion alone does not stop the consumptive process. Stopping antibiotics worsens the sepsis driving the DIC. Warfarin would worsen bleeding and has no role in acute DIC.', 'Medium', 45, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 60-year-old man presents with a rapidly growing neck mass, fever, and weight loss. Biopsy shows diffuse large B-cell lymphoma that is CD20-positive. What is the most appropriate treatment?', '["R-CHOP chemotherapy", "Imatinib", "All-trans retinoic acid plus arsenic trioxide", "Hydroxyurea alone", "Observation"]'::jsonb, 0, 'R-CHOP, rituximab plus cyclophosphamide, doxorubicin, vincristine, and prednisone, is the standard first-line treatment for diffuse large B-cell lymphoma and is potentially curative, with rituximab improving outcomes in CD20-positive disease. Imatinib is a BCR-ABL inhibitor for chronic myeloid leukemia. All-trans retinoic acid plus arsenic trioxide is treatment for acute promyelocytic leukemia. Hydroxyurea provides only temporary cytoreduction and does not treat lymphoma. Observation is inappropriate because diffuse large B-cell lymphoma is aggressive and rapidly fatal without treatment. Staging with PET-CT guides treatment, and central nervous system prophylaxis is added for high-risk disease.', 'Medium', 46, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'An 8-year-old boy presents with a rapidly growing jaw mass and an abdominal mass. Biopsy shows a starry sky pattern, a Ki-67 proliferation index of nearly 100%, and a t(8;14) MYC translocation. What is the most likely diagnosis?', '["Hodgkin lymphoma", "Follicular lymphoma", "Chronic lymphocytic leukemia", "Burkitt lymphoma", "Multiple myeloma"]'::jsonb, 3, 'The starry sky pattern with a near-100% Ki-67 and a MYC translocation t(8;14) is diagnostic of Burkitt lymphoma, a highly aggressive B-cell lymphoma that often involves the jaw in children and requires intensive chemotherapy with central nervous system prophylaxis and tumor lysis precautions. Hodgkin lymphoma has Reed-Sternberg cells and a lower proliferation rate. Follicular lymphoma is indolent and carries t(14;18) involving BCL2. Chronic lymphocytic leukemia is a disease of older adults with mature lymphocytes. Multiple myeloma is a plasma cell disorder with lytic bone lesions and an M protein.', 'Medium', 47, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old woman has painless generalized lymphadenopathy with an indolent course over 2 years. Biopsy shows follicular lymphoma with t(14;18) involving BCL2. She is asymptomatic with low tumor burden. What is the most appropriate initial management?', '["Immediate R-CHOP chemotherapy", "Watchful waiting", "Imatinib", "Splenectomy", "All-trans retinoic acid plus arsenic trioxide"]'::jsonb, 1, 'Asymptomatic low-burden follicular lymphoma is managed with watchful waiting because early treatment does not improve survival in this indolent disease; therapy is started when there is symptomatic or high tumor burden disease by GELF criteria. R-CHOP is reserved for symptomatic or high tumor burden disease. Imatinib is a BCR-ABL inhibitor for chronic myeloid leukemia. Splenectomy is not a treatment for follicular lymphoma. All-trans retinoic acid plus arsenic trioxide is treatment for acute promyelocytic leukemia. Treatment is indicated for symptomatic disease, bulky nodes, cytopenias, or rapid progression, and options include rituximab-based chemoimmunotherapy.', 'Medium', 48, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 68-year-old man presents with back pain and fatigue. His hemoglobin is 9.5 g/dL, calcium 12.5 mg/dL, creatinine 2.4 mg/dL, and total protein 10.5 g/dL with an M-spike on electrophoresis. Bone marrow shows 40% plasma cells, and skeletal survey shows lytic lesions. What is the most likely diagnosis?', '["Monoclonal gammopathy of undetermined significance", "Waldenstrom macroglobulinemia", "Chronic lymphocytic leukemia", "Metastatic carcinoma", "Multiple myeloma"]'::jsonb, 4, 'This patient has CRAB features of multiple myeloma: hypercalcemia, renal failure, anemia, and lytic bone lesions, with more than 10% clonal plasma cells in the marrow and an M protein. Monoclonal gammopathy of undetermined significance has an M protein without end-organ damage. Waldenstrom macroglobulinemia produces an IgM paraprotein with lymphoplasmacytic infiltration. Chronic lymphocytic leukemia causes lymphocytosis, not an M-spike. Metastatic carcinoma can cause lytic lesions but does not produce an M-spike or marrow plasmacytosis. Diagnosis requires either 10% or more clonal plasma cells or a biopsy-proven plasmacytoma plus a myeloma-defining event such as a CRAB feature.', 'Medium', 49, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 65-year-old man is newly diagnosed with multiple myeloma and is eligible for stem cell transplantation. What is the most appropriate initial treatment?', '["Observation", "Imatinib", "Induction with a bortezomib-based triplet followed by autologous stem cell transplant", "All-trans retinoic acid plus arsenic trioxide", "Splenectomy"]'::jsonb, 2, 'Transplant-eligible multiple myeloma is treated with proteasome inhibitor-based induction, such as bortezomib, lenalidomide, and dexamethasone, followed by high-dose chemotherapy and autologous stem cell transplant, which prolongs remission and survival. Observation is appropriate only for smoldering myeloma without end-organ damage. Imatinib is a BCR-ABL inhibitor for chronic myeloid leukemia. All-trans retinoic acid plus arsenic trioxide is treatment for acute promyelocytic leukemia. Splenectomy has no role in myeloma therapy. After transplant, maintenance lenalidomide prolongs progression-free survival. Transplant-ineligible patients receive continuous triplet therapy without transplant.', 'Medium', 50, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 70-year-old woman with multiple myeloma develops acute kidney injury. Her blood urea nitrogen is disproportionately high relative to creatinine, and urinalysis shows light chains. What is the most likely cause of the acute kidney injury?', '["Light chain cast nephropathy", "Contrast nephropathy", "Prerenal azotemia alone", "Acute interstitial nephritis", "Immune complex glomerulonephritis"]'::jsonb, 0, 'Myeloma kidney is caused by light chain cast nephropathy, in which filtered free light chains precipitate with Tamm-Horsfall protein and obstruct tubules, so management includes hydration and avoiding nephrotoxins and contrast. No contrast was administered, and contrast nephropathy does not produce light chains in the urine. Prerenal azotemia improves with volume and lacks light chain casts. Acute interstitial nephritis presents with fever, rash, and eosinophilia after a drug exposure. Immune complex glomerulonephritis is uncommon in myeloma and would show active urinary sediment with dysmorphic red cells.', 'Hard', 51, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 32-year-old woman presents with petechiae and gum bleeding. Her platelet count is 18 x 10^9/L, with normal hemoglobin and white blood cell count, a normal peripheral smear, and no splenomegaly. What is the most likely diagnosis?', '["Thrombotic thrombocytopenic purpura", "Disseminated intravascular coagulation", "Heparin-induced thrombocytopenia", "Immune thrombocytopenia", "Aplastic anemia"]'::jsonb, 3, 'Isolated thrombocytopenia with normal hemoglobin, white cell count, and smear in a young woman is classic for immune thrombocytopenia, an antibody-mediated platelet destruction and a diagnosis of exclusion. Thrombotic thrombocytopenic purpura also causes hemolytic anemia, schistocytes, and neurologic symptoms. Disseminated intravascular coagulation prolongs the prothrombin time and lowers fibrinogen. Heparin-induced thrombocytopenia requires recent heparin exposure and often causes thrombosis. Aplastic anemia causes pancytopenia with a hypocellular marrow. Diagnosis requires excluding other causes of thrombocytopenia, including drugs, infection, and marrow disorders, and bone marrow examination is done when the presentation is atypical.', 'Medium', 52, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 30-year-old woman with immune thrombocytopenia has a platelet count of 12 x 10^9/L with active mucosal bleeding. What is the most appropriate first-line treatment?', '["Platelet transfusion alone", "Corticosteroids with or without intravenous immunoglobulin", "Immediate splenectomy", "Imatinib", "Observation"]'::jsonb, 1, 'Corticosteroids with or without intravenous immunoglobulin are first-line therapy for immune thrombocytopenia with bleeding because they reduce antibody-mediated platelet destruction and raise the count. Platelet transfusion alone is ineffective because transfused platelets are rapidly destroyed, and it is reserved for life-threatening bleeding. Splenectomy is second-line therapy for refractory disease. Imatinib is a BCR-ABL inhibitor for chronic myeloid leukemia. Observation is unsafe with active mucosal bleeding and a platelet count of 12 x 10^9/L. Intravenous immunoglobulin works faster and is preferred when a rapid platelet rise is needed, such as before an urgent procedure.', 'Medium', 53, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 38-year-old woman presents with fever, confusion, and petechiae. Her hemoglobin is 7.8 g/dL, platelets 22 x 10^9/L, and the smear shows schistocytes. Lactate dehydrogenase is high, creatinine is 1.8 mg/dL, and ADAMTS13 activity is less than 10%. What is the most appropriate urgent treatment?', '["Platelet transfusion", "Heparin infusion", "Corticosteroids alone", "Splenectomy", "Therapeutic plasma exchange"]'::jsonb, 4, 'Severe ADAMTS13 deficiency with microangiopathic hemolytic anemia, thrombocytopenia, and neurologic symptoms defines thrombotic thrombocytopenic purpura, and urgent therapeutic plasma exchange is lifesaving because it removes autoantibodies and replaces ADAMTS13; corticosteroids and caplacizumab are adjuncts. Platelet transfusion worsens microvascular thrombosis and is avoided. Heparin does not treat TTP. Corticosteroids alone are insufficient. Splenectomy is not an acute treatment and is reserved for refractory disease. Treatment must start immediately on clinical suspicion without waiting for ADAMTS13 results, because delays increase mortality substantially.', 'Hard', 54, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 35-year-old woman has microangiopathic hemolytic anemia, thrombocytopenia, renal failure, and neurologic symptoms. Which finding best distinguishes thrombotic thrombocytopenic purpura from hemolytic uremic syndrome?', '["Elevated lactate dehydrogenase", "Schistocytes on the peripheral smear", "Severely reduced ADAMTS13 activity", "Elevated creatinine", "Thrombocytopenia"]'::jsonb, 2, 'Severely reduced ADAMTS13 activity, typically less than 10%, is characteristic of thrombotic thrombocytopenic purpura and is the key distinguishing test. Hemolytic uremic syndrome is usually caused by Shiga toxin-producing Escherichia coli or complement dysregulation and does not show severe ADAMTS13 deficiency. Elevated lactate dehydrogenase, schistocytes, elevated creatinine, and thrombocytopenia occur in both conditions because both are thrombotic microangiopathies with red cell fragmentation and platelet consumption. In hemolytic uremic syndrome, ADAMTS13 activity is usually normal or only mildly reduced, and the disease often follows Shiga toxin-producing Escherichia coli infection or complement dysregulation.', 'Hard', 55, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 60-year-old man on day 7 of heparin therapy has a platelet count fall from 220 x 10^9/L to 90 x 10^9/L and develops new leg swelling. Doppler ultrasound shows a deep vein thrombosis. What is the most likely diagnosis?', '["Heparin-induced thrombocytopenia", "Immune thrombocytopenia", "Disseminated intravascular coagulation", "Thrombotic thrombocytopenic purpura", "Drug-induced marrow suppression"]'::jsonb, 0, 'A platelet fall of more than 50% occurring 5 to 10 days after starting heparin, together with a new thrombosis, is classic for heparin-induced thrombocytopenia, an immune-mediated prothrombotic disorder diagnosed by the 4Ts score and anti-PF4 antibodies. Immune thrombocytopenia causes bleeding rather than thrombosis and lacks the heparin timing. Disseminated intravascular coagulation prolongs clotting times and lowers fibrinogen. Thrombotic thrombocytopenic purpura causes hemolytic anemia with schistocytes and neurologic symptoms. Drug-induced marrow suppression causes pancytopenia rather than isolated thrombocytopenia with thrombosis.', 'Medium', 56, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 62-year-old man with suspected heparin-induced thrombocytopenia has a platelet count of 70 x 10^9/L and an acute deep vein thrombosis. What is the most appropriate next step?', '["Continue heparin and observe", "Start warfarin immediately", "Give platelet transfusion", "Stop all heparin and start a non-heparin anticoagulant such as argatroban", "Give low-molecular-weight heparin"]'::jsonb, 3, 'All heparin must be stopped immediately and a non-heparin anticoagulant such as argatroban started, because continued heparin exposure worsens thrombosis in heparin-induced thrombocytopenia. Continuing heparin and observing allows clot progression. Starting warfarin alone risks venous limb gangrene and is deferred until platelets recover. Platelet transfusion worsens thrombosis. Low-molecular-weight heparin cross-reacts with heparin antibodies and must also be avoided. Warfarin is started only after platelet recovery to avoid venous limb gangrene, and fondaparinux or a direct oral anticoagulant may be used in stable patients. Platelet transfusions are avoided because they fuel thrombosis.', 'Hard', 57, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'An 8-year-old boy has recurrent hemarthroses and prolonged bleeding after minor trauma. His activated partial thromboplastin time is prolonged, prothrombin time and platelet count are normal, and factor VIII activity is 2%. What is the most likely diagnosis?', '["Von Willebrand disease", "Hemophilia A", "Hemophilia B", "Vitamin K deficiency", "Disseminated intravascular coagulation"]'::jsonb, 1, 'Hemophilia A is an X-linked deficiency of factor VIII that causes deep tissue bleeding and hemarthroses with a prolonged activated partial thromboplastin time and normal prothrombin time and platelet count; severe disease has factor VIII activity below 1%. Von Willebrand disease affects von Willebrand factor and typically causes mucocutaneous bleeding with a prolonged bleeding time. Hemophilia B is factor IX deficiency, so factor VIII would be normal. Vitamin K deficiency prolongs the prothrombin time as well. Disseminated intravascular coagulation causes thrombocytopenia, low fibrinogen, and prolonged prothrombin time.', 'Medium', 58, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 22-year-old woman has heavy menstrual bleeding, recurrent epistaxis, and easy bruising since childhood. Her bleeding time is prolonged, von Willebrand factor antigen and activity are low, and factor VIII is normal. What is the most likely diagnosis?', '["Hemophilia A", "Hemophilia B", "Immune thrombocytopenia", "Bernard-Soulier syndrome", "Von Willebrand disease"]'::jsonb, 4, 'Mucocutaneous bleeding with low von Willebrand factor antigen and activity defines von Willebrand disease, the most common inherited bleeding disorder, usually treated with desmopressin or von Willebrand factor concentrate. Hemophilia A and B cause deep tissue bleeding and hemarthroses with low factor VIII or IX, respectively, rather than mucocutaneous bleeding. Immune thrombocytopenia causes thrombocytopenia, but this patient''s platelet count is normal. Bernard-Soulier syndrome causes thrombocytopenia with giant platelets, which are absent here. Type 1 is the most common form and involves a quantitative deficiency, while type 2 involves qualitative defects and type 3 is a severe quantitative deficiency.', 'Medium', 59, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 70-year-old woman with sepsis develops bleeding from intravenous sites and petechiae. Her platelets are 45 x 10^9/L, prothrombin time and activated partial thromboplastin time are prolonged, fibrinogen is low, and D-dimer is markedly elevated. What is the most likely diagnosis?', '["Immune thrombocytopenia", "Thrombotic thrombocytopenic purpura", "Disseminated intravascular coagulation", "Heparin-induced thrombocytopenia", "Vitamin K deficiency"]'::jsonb, 2, 'Sepsis with bleeding, thrombocytopenia, prolonged prothrombin time and activated partial thromboplastin time, low fibrinogen, and markedly elevated D-dimer is classic for disseminated intravascular coagulation, a consumptive coagulopathy in which clotting factors and platelets are consumed. Immune thrombocytopenia has normal coagulation tests and fibrinogen. Thrombotic thrombocytopenic purpura has normal prothrombin time and fibrinogen with schistocytes and neurologic symptoms. Heparin-induced thrombocytopenia requires recent heparin exposure and causes thrombosis. Vitamin K deficiency prolongs the prothrombin time but does not cause thrombocytopenia or low fibrinogen.', 'Medium', 60, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 50-year-old woman with no family history of breast cancer and no prior breast disease asks about screening. She is healthy, has never had a mammogram, and has no breast symptoms. She takes no medications and has no known BRCA mutation. According to current US Preventive Services Task Force guidance, what is the most appropriate screening recommendation for her?', '["No screening mammography until age 60", "Annual mammography starting now", "Screening mammography every 2 years from age 50 to 74", "Mammography only if she develops a palpable lump", "Annual breast MRI instead of mammography"]'::jsonb, 2, 'Biennial screening mammography from ages 50 to 74 is the USPSTF recommendation for average-risk women, balancing mortality benefit against harms such as false positives and overdiagnosis. Waiting until age 60 would miss the window in which screening most reduces breast cancer mortality, and annual screening increases false-positive rates without a proven mortality advantage over biennial screening in this age group. Mammography only after a lump appears is diagnostic, not screening, and would delay detection. Breast MRI is reserved for high-risk women, such as BRCA carriers, and is not a screening tool for average-risk patients.', 'Easy', 61, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old woman presents with a painless, firm, fixed mass in the upper outer quadrant of her right breast noticed 2 months ago. She also reports nipple retraction and dimpling of the overlying skin. There is no discharge, fever, or trauma. Examination confirms a 3-cm hard, irregular, nontender mass with an ipsilateral palpable axillary lymph node. What is the most likely diagnosis?', '["Invasive ductal carcinoma", "Fibroadenoma", "Breast abscess", "Fat necrosis", "Fibrocystic change"]'::jsonb, 0, 'Invasive ductal carcinoma is the most common breast cancer and typically presents as a painless, hard, irregular, fixed mass in the upper outer quadrant, often with skin dimpling, nipple retraction, and axillary nodal involvement. A fibroadenoma is usually a smooth, mobile, rubbery mass in a younger woman and does not fix to skin or cause retraction. A breast abscess is painful, erythematous, and febrile, usually in a lactating woman. Fat necrosis follows trauma and can mimic cancer but usually has a history of injury. Fibrocystic change causes bilateral, tender, lumpy breasts that fluctuate with the menstrual cycle rather than a single fixed mass.', 'Medium', 62, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 48-year-old postmenopausal woman undergoes lumpectomy for a 1.8-cm invasive ductal carcinoma that is estrogen receptor-positive, progesterone receptor-positive, and HER2-negative, with negative sentinel lymph nodes and clear margins. She has no distant metastases on staging. What is the most appropriate adjuvant systemic therapy?', '["Cytotoxic chemotherapy with doxorubicin and cyclophosphamide only", "Trastuzumab-based targeted therapy", "No systemic therapy, surgery alone is sufficient", "Radiation therapy alone without systemic treatment", "Endocrine therapy with an aromatase inhibitor"]'::jsonb, 4, 'For postmenopausal women with hormone receptor-positive, HER2-negative, node-negative early breast cancer, adjuvant endocrine therapy with an aromatase inhibitor substantially reduces recurrence and improves survival, and it is the cornerstone of systemic treatment. Cytotoxic chemotherapy is generally reserved for higher-risk disease, such as node-positive or triple-negative tumors, and adds toxicity without clear benefit here. Trastuzumab targets HER2-positive tumors and has no role in a HER2-negative cancer. Surgery alone leaves a substantial recurrence risk in hormone receptor-positive disease, and radiation reduces local recurrence but does not address systemic micrometastases the way endocrine therapy does.', 'Medium', 63, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 52-year-old man with no family history of colorectal cancer, no prior polyps, and no symptoms asks about colorectal cancer screening. He has never been screened. His medical history is unremarkable and he takes no medications. What is the most appropriate screening test to offer him?', '["Annual fecal occult blood testing only", "Flexible sigmoidoscopy alone", "CT colonography only if he refuses all other tests", "No screening is needed until age 60", "Colonoscopy"]'::jsonb, 4, 'Colonoscopy every 10 years is the preferred screening strategy for average-risk adults starting at age 45, because it visualizes the entire colon and allows polypectomy during the same procedure, directly preventing cancer. Annual fecal occult blood testing is an acceptable alternative but is less sensitive and requires colonoscopy for any positive result. Flexible sigmoidoscopy examines only the distal colon and misses right-sided lesions. CT colonography is an alternative for patients who cannot undergo colonoscopy, not the first choice. Waiting until age 60 would miss the age range in which screening prevents the most cancers and deaths.', 'Easy', 64, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 62-year-old man presents with 4 months of fatigue, unintentional 8-kg weight loss, and a change in bowel habits with narrower stools. Laboratory studies show iron deficiency anemia with hemoglobin 9.8 g/dL and low ferritin. He has no family history of colorectal cancer and no prior colonoscopy. Digital rectal examination is normal. What is the best initial diagnostic test?', '["Barium enema", "Fecal occult blood test", "Flexible sigmoidoscopy", "Colonoscopy", "CT abdomen without contrast"]'::jsonb, 3, 'Colonoscopy is the best initial test for a man with iron deficiency anemia, weight loss, and altered bowel habits, because it can directly visualize and biopsy a suspected left-sided colon cancer and evaluate the entire colon. A barium enema is less sensitive and cannot obtain tissue. Fecal occult blood testing is a screening tool, not a diagnostic test for a symptomatic patient with anemia. Flexible sigmoidoscopy misses right-sided lesions and cannot fully evaluate the colon. CT without contrast may show a mass but cannot provide histology, and it is not the preferred first test when colonoscopy is available and safe.', 'Medium', 65, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 58-year-old woman undergoes right hemicolectomy for a stage III (T3N1M0) adenocarcinoma of the ascending colon with 2 of 18 lymph nodes positive. Her postoperative recovery is uncomplicated and staging shows no distant metastases. What is the most appropriate adjuvant treatment?', '["Observation alone with surveillance colonoscopy", "Radiation therapy to the abdomen", "Adjuvant chemotherapy with a fluoropyrimidine plus oxaliplatin (FOLFOX)", "Single-agent capecitabine only", "Immunotherapy with a PD-1 inhibitor"]'::jsonb, 2, 'Adjuvant chemotherapy with FOLFOX is standard for stage III colon cancer, because it significantly improves disease-free and overall survival after curative resection by eradicating micrometastatic disease. Observation alone is inadequate for node-positive disease, which carries a high recurrence risk. Radiation has a limited role in colon cancer, unlike rectal cancer, because the colon is mobile and radiation adds toxicity without proven benefit. Single-agent capecitabine is an option for patients who cannot tolerate oxaliplatin, but combination therapy is preferred in a fit 58-year-old. PD-1 inhibitors are used in metastatic mismatch-repair-deficient tumors, not as standard adjuvant therapy for stage III disease.', 'Medium', 66, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old man with no urinary symptoms, no family history of prostate cancer, and no prior PSA testing asks whether he should have his PSA checked. He is healthy, has a life expectancy well over 10 years, and has read conflicting information online. What is the most appropriate approach to prostate cancer screening for this patient?', '["Shared decision-making about PSA testing, discussing benefits and harms", "Routine annual PSA testing without discussion", "No PSA testing under any circumstances", "PSA testing only after age 65", "Digital rectal examination alone instead of PSA"]'::jsonb, 0, 'For men aged 55 to 69, the USPSTF recommends individualized shared decision-making about PSA screening, because PSA testing modestly reduces prostate cancer mortality but carries harms including false positives, unnecessary biopsies, and overdiagnosis of indolent cancers. Routine annual PSA without discussion ignores these trade-offs and the patient''s preferences. Refusing PSA testing outright denies a potentially beneficial test to an informed patient who may value it. Delaying until age 65 misses the window where screening is most often considered. Digital rectal examination alone is less sensitive than PSA and is not a substitute for a discussed screening strategy.', 'Medium', 67, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 68-year-old man presents with progressive urinary hesitancy, nocturia, and one episode of urinary retention requiring catheterization. Digital rectal examination reveals an enlarged, hard, nodular prostate with loss of the median sulcus. Serum PSA is 42 ng/mL. There is no fever or dysuria. What is the most appropriate next step in diagnosis?', '["Start finasteride and recheck PSA in 3 months", "Transurethral resection of the prostate", "Transrectal ultrasound-guided prostate biopsy", "Radical prostatectomy", "CT scan of the abdomen and pelvis"]'::jsonb, 2, 'A markedly elevated PSA of 42 ng/mL with a hard, nodular prostate is highly suspicious for prostate adenocarcinoma, and the most appropriate next step is tissue diagnosis with transrectal ultrasound-guided prostate biopsy, which confirms the diagnosis and provides Gleason grading to guide treatment. Finasteride would lower PSA artificially and delay diagnosis without addressing the underlying cancer. Transurethral resection is a treatment for benign prostatic obstruction, not a diagnostic step for suspected cancer. Radical prostatectomy is a treatment decision that requires histologic confirmation first. CT scanning can stage known cancer but cannot establish the diagnosis and is not the first step.', 'Medium', 68, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 72-year-old man is found to have localized prostate cancer with a PSA of 6 ng/mL, Gleason score 3+3=6, clinical stage T1c, and no metastases on imaging. He is otherwise healthy with a life expectancy of more than 10 years and is concerned about treatment side effects. What is the most appropriate management?', '["Immediate radical prostatectomy", "Androgen deprivation therapy alone", "External beam radiation with concurrent chemotherapy", "Bilateral orchiectomy", "Active surveillance with serial PSA and repeat biopsy"]'::jsonb, 4, 'Active surveillance is the preferred management for low-risk localized prostate cancer, defined by Gleason 6, PSA below 10 ng/mL, and stage T1c-T2a, because these tumors rarely progress and surveillance avoids the urinary and sexual side effects of definitive treatment while monitoring for progression. Immediate prostatectomy exposes the patient to incontinence and erectile dysfunction without a proven survival advantage in low-risk disease. Androgen deprivation therapy alone is not curative for localized disease and causes significant systemic side effects. Radiation with chemotherapy is reserved for higher-risk or locally advanced disease. Bilateral orchiectomy is a form of androgen deprivation, not a treatment for low-risk localized cancer.', 'Medium', 69, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 64-year-old man with a 40 pack-year smoking history is found to have a 3-cm peripheral lung mass. PET-CT shows the mass is FDG-avid with an ipsilateral hilar lymph node, but no distant metastases. Biopsy confirms adenocarcinoma of the lung. He has good performance status and no significant comorbidities. What is the most appropriate next step in staging and management?', '["Start palliative chemotherapy immediately", "Surgical resection without further staging", "Brain MRI and mediastinal staging with endobronchial ultrasound", "Whole-body bone scan only", "Observation with repeat imaging in 6 months"]'::jsonb, 2, 'For a potentially resectable non-small cell lung cancer with hilar nodal involvement, complete staging with brain MRI and mediastinal nodal staging by endobronchial ultrasound is required before deciding on surgery, because mediastinal nodal status determines resectability and whether neoadjuvant therapy is needed. Starting palliative chemotherapy assumes unresectable disease without proving it. Proceeding directly to surgery risks operating on a patient with occult N2 or brain disease. A bone scan alone is insufficient for mediastinal and brain staging. Observation would delay curative-intent treatment for a cancer that is potentially resectable.', 'Hard', 70, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 60-year-old man with a 30 pack-year smoking history presents with a 3-month history of cough and weight loss. Imaging shows a central lung mass, and biopsy confirms small cell lung cancer. Laboratory studies show serum sodium 128 mEq/L with low serum osmolality, high urine osmolality, and high urine sodium. He is clinically euvolemic with normal thyroid and adrenal function. What is the most likely cause of his hyponatremia?', '["Cerebral salt wasting", "Diuretic-induced hyponatremia", "Adrenal insufficiency", "Syndrome of inappropriate antidiuretic hormone secretion", "Hypothyroidism"]'::jsonb, 3, 'Small cell lung cancer commonly causes paraneoplastic SIADH through ectopic ADH secretion, producing euvolemic hyponatremia with low serum osmolality, inappropriately concentrated urine, and high urine sodium, exactly as seen here. Cerebral salt wasting causes hypovolemia with renal salt loss, typically after intracranial disease, not a euvolemic picture. The patient takes no diuretics, so diuretic-induced hyponatremia does not apply. Adrenal insufficiency and hypothyroidism can cause hyponatremia but are excluded by the normal adrenal and thyroid function, and neither is the classic paraneoplastic syndrome of small cell lung cancer.', 'Medium', 71, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 58-year-old man with newly diagnosed small cell lung cancer presents with 2 days of progressive facial swelling, dyspnea when lying flat, and distended neck veins. His face is plethoric and he has dilated veins over the anterior chest wall. He is afebrile and his lungs are clear. What is the most likely diagnosis?', '["Superior vena cava syndrome", "Pulmonary embolism", "Congestive heart failure", "Angioedema", "Pericardial tamponade"]'::jsonb, 0, 'Superior vena cava syndrome from malignant compression or invasion of the SVC by small cell lung cancer produces facial swelling and plethora, dyspnea, orthopnea, distended neck veins, and dilated chest wall collaterals, matching this presentation. Pulmonary embolism typically causes pleuritic chest pain, tachycardia, and hypoxemia rather than facial swelling. Congestive heart failure causes peripheral edema, elevated jugular venous pressure, and pulmonary crackles, not facial plethora with chest collaterals. Angioedema causes rapid lip and tongue swelling, usually with an allergic trigger, and does not produce dilated chest veins. Pericardial tamponade causes hypotension, muffled heart sounds, and pulsus paradoxus, not facial swelling.', 'Medium', 72, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 58-year-old postmenopausal woman presents with 3 months of progressive abdominal bloating, early satiety, and a 5-kg weight loss. Examination reveals a large pelvic mass and shifting dullness consistent with ascites. CA-125 is markedly elevated at 850 U/mL. She has no prior gynecologic disease. What is the most appropriate next step?', '["Start oral contraceptives to suppress ovarian function", "Diagnostic laparoscopy without imaging", "CT scan of the abdomen and pelvis with referral to gynecologic oncology", "Serum pregnancy test and reassurance", "Pelvic ultrasound only, with routine follow-up in 6 months"]'::jsonb, 2, 'A postmenopausal woman with a pelvic mass, ascites, and a markedly elevated CA-125 most likely has epithelial ovarian cancer, and the most appropriate next step is CT imaging of the abdomen and pelvis for staging with urgent referral to gynecologic oncology, because these patients have better outcomes when surgery is performed by a gynecologic oncologist. Oral contraceptives do not treat ovarian cancer and would delay care. Diagnostic laparoscopy without imaging skips staging and risks tumor spillage. A pregnancy test is irrelevant in a postmenopausal woman, and reassurance is unsafe. Ultrasound alone is insufficient for staging, and a 6-month delay would allow advanced disease to progress.', 'Medium', 73, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 62-year-old postmenopausal woman presents with 2 months of painless vaginal bleeding. She is obese with a BMI of 38 kg/m2 and has type 2 diabetes and hypertension. She has never used hormone replacement therapy. Transvaginal ultrasound shows an endometrial thickness of 12 mm. What is the best initial diagnostic test?', '["Serum CA-125 level", "Hysteroscopy with dilation and curettage", "Pap smear", "Endometrial biopsy", "CT scan of the pelvis"]'::jsonb, 3, 'Endometrial biopsy is the best initial test for postmenopausal bleeding with a thickened endometrium, because it directly samples the endometrium and can diagnose endometrial adenocarcinoma, which is the most likely diagnosis in an obese postmenopausal woman with diabetes. Serum CA-125 is a marker for ovarian cancer, not the primary test for endometrial bleeding. Hysteroscopy with dilation and curettage is more invasive and is reserved for when office biopsy is nondiagnostic. A Pap smear screens for cervical cancer and does not evaluate the endometrium. CT scanning cannot provide histology and is used for staging after a tissue diagnosis, not as the initial diagnostic test.', 'Medium', 74, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old woman undergoes staging for a newly diagnosed stage III epithelial ovarian cancer with peritoneal metastases. She has good performance status, normal renal and hepatic function, and no significant comorbidities. What is the most appropriate initial treatment?', '["Chemotherapy alone without surgery", "Radiation therapy to the pelvis", "Hormonal therapy with tamoxifen", "Observation with serial CA-125 monitoring", "Primary cytoreductive surgery followed by platinum-based chemotherapy"]'::jsonb, 4, 'For advanced epithelial ovarian cancer, primary cytoreductive surgery to achieve maximal tumor debulking followed by platinum-based combination chemotherapy is the standard of care, because optimal debulking significantly improves survival. Chemotherapy alone is used when the patient is unfit for surgery or the disease is deemed unresectable, but this patient is a good surgical candidate. Radiation has a limited role in ovarian cancer because of widespread peritoneal disease and toxicity. Hormonal therapy is not effective primary treatment for epithelial ovarian cancer. Observation with CA-125 monitoring would allow a potentially treatable advanced cancer to progress unchecked.', 'Medium', 75, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 68-year-old man presents with 2 months of painless jaundice, pruritus, dark urine, pale stools, and a 10-kg weight loss. Examination reveals a palpable, nontender gallbladder. Laboratory studies show markedly elevated total and direct bilirubin with elevated alkaline phosphatase. He has no history of alcohol use or gallstones. What is the best initial imaging test?', '["Abdominal ultrasound", "CT abdomen with contrast using a pancreatic protocol", "ERCP", "MRCP", "Plain abdominal radiograph"]'::jsonb, 1, 'CT of the abdomen with intravenous contrast using a pancreatic protocol is the best initial test for suspected pancreatic adenocarcinoma presenting with painless jaundice and a Courvoisier gallbladder, because it characterizes the pancreatic mass, assesses vascular involvement, and stages the disease to determine resectability. Ultrasound can show biliary dilation but poorly visualizes the pancreas. ERCP is therapeutic for biliary decompression and is not the initial diagnostic test. MRCP is useful for biliary anatomy but is less effective than CT for staging pancreatic cancer. A plain radiograph has no role in evaluating painless jaundice or a pancreatic mass.', 'Medium', 76, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 66-year-old woman is diagnosed with locally advanced, unresectable pancreatic adenocarcinoma involving the superior mesenteric artery, without distant metastases. She has good performance status with an ECOG score of 1 and normal organ function. What is the most appropriate treatment?', '["Systemic chemotherapy with FOLFIRINOX or gemcitabine plus nab-paclitaxel", "Immediate Whipple procedure", "Radiation therapy alone", "Palliative care only with no anticancer therapy", "Surgical biliary bypass without chemotherapy"]'::jsonb, 0, 'For locally advanced unresectable pancreatic cancer in a fit patient, systemic chemotherapy with FOLFIRINOX or gemcitabine plus nab-paclitaxel is the standard of care, because it improves survival and may occasionally downstage the tumor enough to permit later resection. A Whipple procedure is not possible when the tumor encases major vessels. Radiation alone is less effective than chemotherapy and is not the primary treatment. Palliative care alone is appropriate only for patients who are unfit for chemotherapy or decline it. Surgical biliary bypass addresses obstruction but does not treat the cancer itself and is not a substitute for systemic therapy.', 'Hard', 77, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 45-year-old woman receiving adjuvant chemotherapy for breast cancer presents with fever of 38.5 C, chills, and malaise 10 days after her last cycle. Her absolute neutrophil count is 300 cells/mm3, and she has no localizing symptoms. Blood pressure is 110/70 mmHg and she is alert. What is the most appropriate initial management?', '["Outpatient oral antibiotics after a single dose of acetaminophen", "Wait for the fever to resolve without antibiotics", "Oral ciprofloxacin alone", "Granulocyte colony-stimulating factor alone without antibiotics", "Blood cultures followed by empiric intravenous cefepime"]'::jsonb, 4, 'Febrile neutropenia is a medical emergency, and the standard initial management is prompt blood cultures followed immediately by empiric intravenous antipseudomonal beta-lactam therapy such as cefepime, because delays increase mortality from Gram-negative sepsis. Outpatient oral antibiotics are reserved for carefully selected low-risk patients and are not appropriate as the first step before cultures and assessment. Waiting without antibiotics is dangerous in a neutropenic patient with fever. Ciprofloxacin alone lacks adequate Gram-positive and Pseudomonas coverage for initial empiric therapy. Granulocyte colony-stimulating factor is an adjunct that does not replace immediate antibiotics in febrile neutropenia.', 'Medium', 78, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 52-year-old man with acute myeloid leukemia develops fever of 39.0 C and hypotension with a blood pressure of 85/50 mmHg on day 12 of induction chemotherapy. His absolute neutrophil count is 100 cells/mm3. He has a central venous catheter with erythema at the insertion site and a new skin rash. What is the most appropriate empiric antibiotic regimen?', '["Cefepime alone", "Vancomycin alone", "Oral amoxicillin-clavulanate", "Cefepime plus vancomycin", "Ceftriaxone alone"]'::jsonb, 3, 'In high-risk febrile neutropenia with hypotension, skin or soft tissue infection, or a central line infection, vancomycin should be added to an antipseudomonal beta-lactam such as cefepime to cover methicillin-resistant Staphylococcus aureus and other Gram-positive organisms. Cefepime alone provides excellent Gram-negative and Pseudomonas coverage but inadequate MRSA coverage in this high-risk setting. Vancomycin alone lacks Gram-negative coverage and would leave the patient unprotected against Pseudomonas sepsis. Oral amoxicillin-clavulanate is inadequate for a hypotensive, profoundly neutropenic patient. Ceftriaxone lacks reliable antipseudomonal activity and is not appropriate empiric monotherapy for febrile neutropenia.', 'Hard', 79, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 38-year-old woman with early-stage breast cancer develops fever of 38.4 C with an absolute neutrophil count of 600 cells/mm3 after her second cycle of chemotherapy. She is hemodynamically stable, has no focal infection, no comorbidities, and a MASCC risk score of 24, indicating low risk. She lives near the hospital and has reliable follow-up. What is the most appropriate management?', '["Admission for intravenous antibiotics indefinitely", "Outpatient oral ciprofloxacin plus amoxicillin-clavulanate after initial evaluation", "No antibiotics, observation only", "Intravenous vancomycin alone", "Immediate admission to the intensive care unit"]'::jsonb, 1, 'Low-risk febrile neutropenia, identified by a MASCC score of 21 or higher with no high-risk features, can be managed with outpatient oral antibiotics such as ciprofloxacin plus amoxicillin-clavulanate after initial evaluation, cultures, and a first dose, provided the patient is stable and has reliable follow-up. Indefinite intravenous antibiotics are unnecessary for a low-risk patient and expose her to hospital-acquired complications. Observation without antibiotics is unsafe in any neutropenic patient with fever. Vancomycin alone lacks Gram-negative coverage and is not appropriate empiric therapy. Intensive care admission is reserved for hemodynamically unstable or critically ill patients, which she is not.', 'Hard', 80, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 22-year-old man with newly diagnosed Burkitt lymphoma begins chemotherapy. On day 2 he develops oliguria, and laboratory studies show potassium 6.1 mEq/L, phosphate 7.2 mg/dL, calcium 6.8 mg/dL, uric acid 14 mg/dL, and creatinine 2.4 mg/dL. He is alert with no ECG changes. What is the most likely diagnosis and the most appropriate initial management?', '["Acute kidney injury from dehydration; give a fluid bolus only", "Tumor lysis syndrome; aggressive intravenous hydration plus rasburicase", "Sepsis; start broad-spectrum antibiotics", "Hypercalcemia of malignancy; give zoledronic acid", "Contrast nephropathy; hold nephrotoxic drugs only"]'::jsonb, 1, 'This is tumor lysis syndrome, a complication of rapidly proliferating hematologic malignancies after chemotherapy, characterized by hyperkalemia, hyperphosphatemia, hypocalcemia, hyperuricemia, and acute kidney injury from uric acid and calcium phosphate precipitation. The most appropriate initial management is aggressive intravenous hydration to maintain high urine output plus rasburicase to rapidly lower uric acid. A fluid bolus alone does not address the severe metabolic derangements. Sepsis does not explain this characteristic laboratory pattern. Hypercalcemia of malignancy causes high, not low, calcium. Contrast nephropathy does not produce hyperkalemia, hyperphosphatemia, and hyperuricemia together.', 'Medium', 81, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'An 18-year-old man is about to start induction chemotherapy for acute lymphoblastic leukemia. His baseline laboratory studies show a white blood cell count of 180,000/mm3 with a lactate dehydrogenase level three times the upper limit of normal. His renal function and electrolytes are currently normal. What is the most appropriate prophylaxis against tumor lysis syndrome?', '["Aggressive intravenous hydration plus rasburicase", "No prophylaxis is needed before chemotherapy", "Oral calcium supplements", "Intravenous zoledronic acid", "Allopurinol alone without hydration"]'::jsonb, 0, 'This patient is at high risk for tumor lysis syndrome because of a very high white blood cell count and markedly elevated LDH, so prophylaxis with aggressive intravenous hydration plus rasburicase is appropriate, since rasburicase rapidly lowers uric acid and prevents urate nephropathy. No prophylaxis would be unsafe in a high-risk patient starting induction therapy. Oral calcium supplements do not prevent tumor lysis syndrome and could worsen calcium phosphate precipitation. Zoledronic acid treats hypercalcemia of malignancy, not tumor lysis syndrome. Allopurinol alone prevents new uric acid formation but does not lower existing uric acid, and hydration is essential regardless of the urate-lowering agent chosen.', 'Medium', 82, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 25-year-old woman with high-grade non-Hodgkin lymphoma develops acute kidney injury 48 hours after starting chemotherapy. Laboratory studies show potassium 6.0 mEq/L, phosphate 6.8 mg/dL, calcium 7.0 mg/dL, and uric acid 12 mg/dL. Which of the following best describes the laboratory pattern of tumor lysis syndrome?', '["Hyperkalemia, hyperphosphatemia, hypercalcemia, and hyperuricemia", "Hypokalemia, hypophosphatemia, hypercalcemia, and hyperuricemia", "Hyperkalemia, hyperphosphatemia, hypocalcemia, and hyperuricemia", "Hyperkalemia, hypophosphatemia, hypocalcemia, and hypouricemia", "Hypokalemia, hyperphosphatemia, hypocalcemia, and hyperuricemia"]'::jsonb, 2, 'Tumor lysis syndrome is defined by hyperkalemia, hyperphosphatemia, hypocalcemia, and hyperuricemia, resulting from the massive release of intracellular contents when tumor cells lyse: potassium and phosphate are released, phosphate binds calcium causing hypocalcemia, and nucleic acids are metabolized to uric acid. The first option is wrong because calcium is low, not high, in tumor lysis syndrome. The second option is wrong because potassium is elevated, not low. The fourth option is wrong because phosphate and uric acid are both elevated. The fifth option is wrong because potassium is elevated and phosphate is elevated, not low.', 'Easy', 83, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 70-year-old woman with metastatic breast cancer to bone presents with 2 days of confusion, constipation, and polyuria. Laboratory studies show serum calcium 13.2 mg/dL, albumin 3.8 g/dL, and normal parathyroid hormone. She is mildly dehydrated with a blood pressure of 100/60 mmHg. What is the most appropriate initial management?', '["Oral calcium supplements and observation", "Intravenous normal saline followed by zoledronic acid", "Immediate hemodialysis", "Subcutaneous calcitonin alone", "High-dose glucocorticoids alone"]'::jsonb, 1, 'Hypercalcemia of malignancy in a patient with bone metastases should be treated first with aggressive intravenous normal saline to restore volume and promote calciuresis, followed by a bisphosphonate such as zoledronic acid, which inhibits osteoclast-mediated bone resorption and provides durable calcium lowering. Oral calcium supplements would worsen the hypercalcemia. Hemodialysis is reserved for severe, refractory hypercalcemia with renal failure, not as initial therapy. Calcitonin alone lowers calcium quickly but only transiently and is an adjunct, not definitive treatment. High-dose glucocorticoids are useful for calcitriol-mediated hypercalcemia, such as in lymphoma or sarcoidosis, but are not first-line for osteolytic bone metastases.', 'Medium', 84, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 66-year-old man with squamous cell carcinoma of the lung presents with confusion, constipation, and polyuria. Laboratory studies show serum calcium 13.5 mg/dL, suppressed parathyroid hormone, and elevated parathyroid hormone-related protein. Bone scan shows no metastases. What is the most likely mechanism of his hypercalcemia?', '["Osteolytic bone metastases", "Humoral hypercalcemia of malignancy mediated by PTHrP", "Primary hyperparathyroidism", "Vitamin D intoxication", "Multiple myeloma"]'::jsonb, 1, 'Squamous cell carcinoma of the lung classically causes humoral hypercalcemia of malignancy through ectopic secretion of parathyroid hormone-related protein, which stimulates osteoclast activity and renal calcium reabsorption despite a suppressed native parathyroid hormone level. Osteolytic bone metastases are excluded by the negative bone scan. Primary hyperparathyroidism would show an elevated, not suppressed, parathyroid hormone level. Vitamin D intoxication raises 25-hydroxyvitamin D and does not produce elevated PTHrP. Multiple myeloma causes hypercalcemia through osteoclast-activating factors, but this patient has squamous cell lung cancer with a clearly elevated PTHrP level.', 'Medium', 85, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 64-year-old man with metastatic prostate cancer to the spine presents with 1 week of progressive mid-back pain, bilateral leg weakness, and new urinary retention. Examination shows decreased lower extremity strength, hyperreflexia, and a sensory level at T8. He is afebrile with normal vital signs. What is the most appropriate next step?', '["Oral analgesics and outpatient follow-up in 1 week", "Lumbar puncture", "Plain radiographs of the thoracic spine", "Urgent MRI of the entire spine with high-dose dexamethasone", "Physical therapy referral"]'::jsonb, 3, 'Progressive back pain with bilateral leg weakness, hyperreflexia, a sensory level, and urinary retention in a patient with metastatic cancer to the spine indicates malignant spinal cord compression, a neurologic emergency, and the most appropriate next step is urgent MRI of the entire spine with immediate high-dose dexamethasone to reduce edema and preserve neurologic function. Oral analgesics and delayed follow-up would allow irreversible cord injury. Lumbar puncture is contraindicated with suspected cord compression and provides no benefit. Plain radiographs cannot adequately evaluate epidural disease or cord compression. Physical therapy does not address the underlying compression and would delay definitive treatment.', 'Medium', 86, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 62-year-old woman with metastatic breast cancer has an MRI showing an epidural mass at T6 compressing the spinal cord, causing progressive leg weakness. She has already received high-dose dexamethasone. She is hemodynamically stable with no spinal instability. What is the most appropriate definitive treatment?', '["Urgent surgical decompression or radiation therapy to the involved spine", "Oral analgesics alone", "Chemotherapy alone without local therapy", "Observation with repeat MRI in 1 month", "Lumbar puncture for diagnosis"]'::jsonb, 0, 'For malignant spinal cord compression with a confirmed epidural mass, definitive treatment is urgent surgical decompression or radiation therapy to the involved segment, in addition to dexamethasone, because local therapy relieves the compression and preserves neurologic function and ambulation. Oral analgesics alone do not address the mechanical compression. Chemotherapy alone acts too slowly to prevent irreversible cord damage. Observation with repeat imaging in a month would allow permanent paralysis to develop. Lumbar puncture is contraindicated in cord compression and would not guide treatment once the diagnosis is established by MRI.', 'Hard', 87, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old woman with small cell lung cancer presents with 3 days of progressive facial swelling, dyspnea, and distended neck veins. She has dilated veins over her anterior chest and her face is plethoric. She is afebrile and her lungs are clear on examination. What is the most appropriate initial diagnostic test?', '["Chest radiograph", "Echocardiogram", "Electrocardiogram", "CT chest with intravenous contrast", "D-dimer level"]'::jsonb, 3, 'Superior vena cava syndrome in a patient with small cell lung cancer requires CT of the chest with intravenous contrast as the initial diagnostic test, because it confirms SVC obstruction, identifies the causative mass, and guides treatment decisions including radiation or stenting. A chest radiograph may show mediastinal widening but cannot adequately define the obstruction. An echocardiogram evaluates cardiac function and pericardial disease, not SVC compression. An electrocardiogram does not diagnose SVC obstruction. A D-dimer is a test for venous thromboembolism and would not explain facial swelling with chest wall collaterals in a patient with known lung cancer.', 'Medium', 88, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 62-year-old man with small cell lung cancer presents with 2 months of progressive proximal muscle weakness in his legs, dry mouth, and difficulty climbing stairs. His strength briefly improves with repeated muscle use. Deep tendon reflexes are diminished. Electromyography shows an incremental response to repetitive nerve stimulation. What is the most likely diagnosis?', '["Myasthenia gravis", "Lambert-Eaton myasthenic syndrome", "Guillain-Barre syndrome", "Polymyositis", "Amyotrophic lateral sclerosis"]'::jsonb, 1, 'Lambert-Eaton myasthenic syndrome is a paraneoplastic disorder associated with small cell lung cancer, caused by antibodies against presynaptic voltage-gated calcium channels, producing proximal leg weakness that improves with repeated use, diminished reflexes, and autonomic symptoms such as dry mouth, with an incremental response on repetitive nerve stimulation. Myasthenia gravis causes weakness that worsens with use, affects ocular and bulbar muscles early, and shows a decremental response. Guillain-Barre syndrome causes rapidly progressive ascending weakness with areflexia, not improvement with exercise. Polymyositis causes proximal weakness with elevated muscle enzymes and no autonomic features. Amyotrophic lateral sclerosis combines upper and lower motor neuron signs and does not improve with repeated use.', 'Hard', 89, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 70-year-old man with metastatic pancreatic cancer presents with severe, constant abdominal pain rated 9 out of 10 that is poorly controlled on acetaminophen and ibuprofen. He is alert, has no bowel obstruction, and his renal function is normal. He has a life expectancy of several months. According to the WHO analgesic ladder, what is the most appropriate next step in pain management?', '["Continue acetaminophen alone and reassess in 1 month", "Add a weak opioid such as codeine", "Start intravenous chemotherapy for pain control", "Refer for surgical resection of the tumor", "Start a strong opioid such as oral morphine"]'::jsonb, 4, 'According to the WHO analgesic ladder, severe cancer pain that is not controlled by non-opioid analgesics should be treated with a strong opioid such as oral morphine, which is the standard of care for moderate to severe cancer pain and should be titrated to effect with laxatives for constipation prophylaxis. Continuing acetaminophen alone leaves severe pain untreated. A weak opioid such as codeine is appropriate only for mild to moderate pain and is insufficient for pain rated 9 out of 10. Intravenous chemotherapy does not provide immediate pain relief and is not an analgesic strategy. Surgical resection is not appropriate for metastatic pancreatic cancer and would not address the immediate pain.', 'Medium', 90, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 68-year-old woman is receiving her first unit of packed red blood cells after hip replacement surgery. Fifteen minutes into the transfusion she develops fever, chills, severe flank pain, and dark red urine. Her blood pressure falls to 88/55 mm Hg. Her hemoglobin has fallen from 9.2 g/dL to 7.1 g/dL, and the plasma is pink. What is the most appropriate immediate next step?', '["Stop the transfusion immediately and maintain intravenous access with normal saline", "Give acetaminophen and diphenhydramine and continue the transfusion at a slower rate", "Administer intravenous furosemide and give supplemental oxygen", "Send a blood culture and start broad-spectrum antibiotics while continuing the transfusion", "Give intravenous methylprednisolone and resume the transfusion after 30 minutes"]'::jsonb, 0, 'This is an acute hemolytic transfusion reaction, most often due to ABO incompatibility from clerical error, with complement-mediated intravascular hemolysis causing fever, flank pain, hemoglobinuria, hypotension, and acute kidney injury. The first and most critical step is to stop the transfusion immediately to limit further incompatible blood, while keeping intravenous access open with saline to support blood pressure and renal perfusion. Continuing the transfusion, as in choices B and E, worsens hemolysis and renal failure. Furosemide is for volume overload, not hemolysis, and may worsen renal perfusion. Antibiotics are for suspected sepsis, but the temporal link to transfusion with hemoglobinuria makes acute hemolysis far more likely, and the transfusion must be stopped first.', 'Medium', 91, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 74-year-old man with heart failure and chronic kidney disease receives two units of packed red blood cells for symptomatic anemia. Within 2 hours he develops severe dyspnea, hypoxemia, and pink frothy sputum. Blood pressure is 178/102 mm Hg, jugular venous pressure is elevated, and chest radiograph shows bilateral pulmonary edema. A repeat BNP is markedly elevated. What is the most likely diagnosis?', '["Transfusion-related acute lung injury", "Acute hemolytic transfusion reaction", "Transfusion-associated circulatory overload", "Anaphylactic transfusion reaction", "Bacterial contamination of the blood product"]'::jsonb, 2, 'Transfusion-associated circulatory overload (TACO) is cardiogenic pulmonary edema from volume overload during transfusion, typically in patients with heart failure or kidney disease, presenting with hypertension, elevated jugular venous pressure, and elevated BNP. Transfusion-related acute lung injury (TRALI) is noncardiogenic, usually with hypotension and a normal BNP, caused by donor antibodies against recipient leukocytes. Acute hemolytic reaction causes fever, flank pain, and hemoglobinuria, not isolated pulmonary edema. Anaphylaxis causes hypotension and bronchospasm rather than hypertension with elevated BNP. Bacterial contamination presents with fever, rigors, and hypotension progressing to shock, not hypertensive pulmonary edema.', 'Medium', 92, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 45-year-old woman with iron deficiency anemia is receiving a packed red blood cell transfusion. Forty-five minutes into the unit she develops a temperature of 38.6°C with chills and rigors. She is hemodynamically stable, has no dyspnea, rash, flank pain, or hypotension, and her urine is clear. What is the most appropriate next step?', '["Immediately discard the unit and give high-dose corticosteroids", "Pause the transfusion, evaluate for hemolysis, and give acetaminophen", "Administer intravenous furosemide and continue the transfusion", "Stop the transfusion permanently and order an emergency type and crossmatch", "Give epinephrine and antihistamines for suspected anaphylaxis"]'::jsonb, 1, 'This is a febrile nonhemolytic transfusion reaction, the most common transfusion reaction, caused by cytokines or antibodies against donor leukocytes. The correct approach is to pause the transfusion, evaluate for hemolysis with a plasma check, LDH, bilirubin, and direct antiglobulin test, and give acetaminophen; the transfusion can often be resumed if hemolysis is excluded. High-dose corticosteroids are not indicated for a simple febrile reaction. Furosemide treats volume overload, which is not present here. Permanently stopping the transfusion is unnecessary if hemolysis is ruled out. Epinephrine and antihistamines are for anaphylaxis, which would cause hypotension, bronchospasm, or angioedema, none of which are present.', 'Medium', 93, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 72-year-old man with atrial fibrillation takes warfarin 5 mg daily. He presents for routine follow-up feeling well, with no bleeding or bruising. His INR is 7.5 (therapeutic range 2.0-3.0). He takes no new medications and has not changed his diet. What is the most appropriate management?', '["Continue warfarin at the same dose and recheck the INR in one week", "Hold warfarin and give intravenous vitamin K 10 mg", "Hold warfarin and give 4-factor prothrombin complex concentrate", "Hold warfarin and give low-dose oral vitamin K", "Hold warfarin and start subcutaneous low-molecular-weight heparin"]'::jsonb, 3, 'A supratherapeutic INR without bleeding is managed by holding warfarin and giving low-dose oral vitamin K (2.5 mg), which lowers the INR gradually over 24 to 48 hours. Continuing warfarin at an INR of 7.5 risks major hemorrhage. Intravenous vitamin K 10 mg is reserved for life-threatening bleeding because it can cause anaphylaxis and prolonged warfarin resistance. Four-factor prothrombin complex concentrate is also reserved for major bleeding, not asymptomatic INR elevation. Bridging with low-molecular-weight heparin is not indicated when there is no bleeding and the INR is already markedly elevated.', 'Medium', 94, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'An 80-year-old woman on warfarin for atrial fibrillation presents with a severe headache, vomiting, and a Glasgow Coma Scale score of 11. CT of the head shows an acute intracerebral hemorrhage. Her INR is 4.2. Her blood pressure is 190/110 mm Hg. What is the most appropriate immediate management for warfarin reversal?', '["Hold warfarin and give low-dose oral vitamin K", "Hold warfarin and give fresh frozen plasma alone", "Hold warfarin and give intravenous vitamin K 10 mg alone", "Hold warfarin and give desmopressin", "Hold warfarin and give 4-factor prothrombin complex concentrate plus intravenous vitamin K"]'::jsonb, 4, 'Life-threatening bleeding on warfarin, such as intracerebral hemorrhage, requires rapid reversal with 4-factor prothrombin complex concentrate, which immediately replaces factors II, VII, IX, and X, plus intravenous vitamin K for sustained factor synthesis. Oral vitamin K acts too slowly for an expanding intracranial bleed. Fresh frozen plasma alone is slower, requires large volumes, and is less effective than concentrate. Intravenous vitamin K alone takes 6 to 24 hours to work, which is too slow here. Desmopressin improves platelet function in uremia or von Willebrand disease but does not reverse warfarin anticoagulation.', 'Medium', 95, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 58-year-old man is on postoperative day 7 after total hip arthroplasty, receiving subcutaneous unfractionated heparin for venous thromboembolism prophylaxis. His platelet count has fallen from 220,000/µL to 90,000/µL, and he has developed a new painful swollen left leg. Doppler ultrasound confirms a deep vein thrombosis. What is the most appropriate next step?', '["Continue heparin and start warfarin immediately", "Stop all heparin products and start argatroban", "Stop heparin and give a platelet transfusion", "Continue heparin and add low-dose aspirin", "Stop heparin and observe without anticoagulation"]'::jsonb, 1, 'This is heparin-induced thrombocytopenia, with a platelet fall of more than 50% occurring 5 to 10 days after heparin exposure and paradoxical thrombosis. All heparin products, including flushes and low-molecular-weight heparin, must be stopped, and a non-heparin anticoagulant such as argatroban, bivalirudin, or fondaparinux started. Warfarin must not be started acutely because it depletes protein C first and worsens thrombosis. Platelet transfusion is contraindicated because it fuels further thrombosis. Continuing heparin worsens the immune-mediated platelet activation, and observation leaves the thrombosis untreated.', 'Hard', 96, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 77-year-old woman taking apixaban for atrial fibrillation presents with massive hematemesis and hypotension. Her hemoglobin is 6.5 g/dL. She took her last dose of apixaban 4 hours ago. Resuscitation with blood products and intravenous proton pump inhibitor is underway. What is the most appropriate specific reversal agent?', '["Protamine sulfate", "Idarucizumab", "Andexanet alfa", "Desmopressin", "Fresh frozen plasma"]'::jsonb, 2, 'Andexanet alfa is a recombinant modified factor Xa decoy protein that specifically reverses the factor Xa inhibitors apixaban and rivaroxaban in life-threatening bleeding. Idarucizumab reverses dabigatran, a direct thrombin inhibitor, not apixaban. Protamine sulfate reverses unfractionated heparin and partially reverses low-molecular-weight heparin. Desmopressin improves platelet function in uremic or von Willebrand-related bleeding but does not reverse anticoagulants. Fresh frozen plasma does not reverse direct oral anticoagulants. Four-factor prothrombin complex concentrate is an alternative when andexanet is unavailable, but it is not the specific reversal agent, and apixaban should be held until bleeding is controlled.', 'Medium', 97, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 60-year-old man with coronary artery disease underwent percutaneous coronary intervention with a drug-eluting stent 3 months ago and takes aspirin and ticagrelor. He now requires urgent laparoscopic cholecystectomy for acute cholecystitis. What is the most appropriate perioperative antiplatelet management?', '["Continue aspirin and hold ticagrelor", "Hold both aspirin and ticagrelor for 7 days", "Continue both aspirin and ticagrelor through surgery", "Hold aspirin and continue ticagrelor", "Stop both agents and start intravenous heparin"]'::jsonb, 0, 'Within 12 months of drug-eluting stent placement, interruption of dual antiplatelet therapy risks catastrophic stent thrombosis. Aspirin should be continued through most surgery, while the P2Y12 inhibitor ticagrelor is held for 3 to 5 days before surgery to reduce bleeding. Holding both agents maximizes stent thrombosis risk. Continuing both agents maximizes surgical bleeding. Holding aspirin while continuing ticagrelor reverses the correct strategy, since aspirin is the safer agent to continue. Heparin does not prevent stent thrombosis and adds bleeding risk.', 'Hard', 98, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 65-year-old woman on clopidogrel after a drug-eluting stent placed 8 months ago is scheduled for elective coronary artery bypass grafting in 1 week. What is the most appropriate preoperative management of her clopidogrel?', '["Continue clopidogrel through the day of surgery", "Stop clopidogrel 24 hours before surgery", "Stop clopidogrel 48 hours before surgery", "Stop clopidogrel 5 days before surgery", "Stop clopidogrel and bridge with low-molecular-weight heparin"]'::jsonb, 3, 'Clopidogrel irreversibly inhibits platelet P2Y12 receptors, and platelets live 7 to 10 days, so it must be stopped 5 days before coronary artery bypass grafting to restore adequate platelet function and reduce major bleeding. Stopping only 24 to 48 hours before surgery leaves most platelets inhibited. Continuing clopidogrel through surgery markedly increases perioperative bleeding. Ticagrelor and prasugrel have different hold times of 3 to 5 and 7 days respectively, but clopidogrel requires 5 days. Bridging with low-molecular-weight heparin does not protect against stent thrombosis and increases bleeding risk, so it is not recommended.', 'Medium', 99, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 70-year-old man on aspirin and clopidogrel after myocardial infarction presents with melena and a hemoglobin of 7.8 g/dL. Endoscopy shows a bleeding duodenal ulcer. He is hemodynamically stable after resuscitation. What is the most appropriate management of his antiplatelet therapy?', '["Continue both agents and give oral iron", "Stop aspirin permanently and continue clopidogrel", "Continue both agents and add a proton pump inhibitor", "Stop both agents and never restart either", "Hold both agents temporarily, give intravenous proton pump inhibitor, and restart aspirin early once bleeding stops"]'::jsonb, 4, 'In acute gastrointestinal bleeding on dual antiplatelet therapy, both agents are held temporarily, an intravenous proton pump inhibitor is given, and resuscitation and transfusion proceed as needed. Aspirin should be restarted early, within 1 to 3 days after hemostasis, to reduce cardiovascular events and stent thrombosis, with clopidogrel resumed later in consultation with cardiology. Continuing both agents worsens bleeding. Stopping aspirin permanently increases the risk of myocardial infarction and stent thrombosis. Never restarting either agent leaves the patient unprotected against cardiovascular events.', 'Medium', 100, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old man with no bleeding history is found to have an isolated prolonged aPTT of 68 seconds (normal 25-35) with a normal PT and platelet count before elective hernia repair. A mixing study with normal plasma does NOT correct the aPTT. What is the most likely explanation?', '["Factor XII deficiency", "Vitamin K deficiency", "Lupus anticoagulant", "Von Willebrand disease", "Factor VII deficiency"]'::jsonb, 2, 'A prolonged aPTT that does not correct on mixing study indicates an inhibitor, most commonly a lupus anticoagulant, an antiphospholipid antibody. Paradoxically, lupus anticoagulant predisposes to thrombosis rather than bleeding, so surgery can usually proceed without factor replacement. Factor XII deficiency prolongs the aPTT but corrects on mixing and causes no bleeding. Vitamin K deficiency prolongs the PT first because factor VII has the shortest half-life. Von Willebrand disease mildly prolongs the aPTT and corrects on mixing. Factor VII deficiency prolongs the PT, not the aPTT.', 'Hard', 101, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 68-year-old man with pancreatic cancer and biliary obstruction presents with easy bruising and epistaxis. Labs show a prolonged PT with a normal aPTT and normal platelet count. He has no liver failure. What is the most likely cause of his coagulopathy?', '["Disseminated intravascular coagulation", "Vitamin K deficiency from fat malabsorption", "Hemophilia A", "Heparin effect", "Factor XIII deficiency"]'::jsonb, 1, 'Biliary obstruction impairs fat absorption and therefore vitamin K absorption, reducing synthesis of factors II, VII, IX, and X. Because factor VII has the shortest half-life, the PT prolongs first while the aPTT remains normal early on. Disseminated intravascular coagulation would cause thrombocytopenia, low fibrinogen, elevated D-dimer, and prolongation of both PT and aPTT. Hemophilia A prolongs the aPTT, not the PT. Heparin prolongs the aPTT. Factor XIII deficiency causes bleeding with normal PT and aPTT because factor XIII acts after fibrin formation.', 'Medium', 102, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 40-year-old woman presents with petechiae, gum bleeding, and heavy menses for 2 weeks. Platelet count is 28,000/µL. Hemoglobin, white cell count, PT, and aPTT are normal. Peripheral smear shows no schistocytes or blasts. She takes no medications. What is the most likely diagnosis?', '["Immune thrombocytopenia", "Thrombotic thrombocytopenic purpura", "Disseminated intravascular coagulation", "Acute leukemia", "Heparin-induced thrombocytopenia"]'::jsonb, 0, 'Isolated thrombocytopenia with mucocutaneous bleeding, normal other cell lines, and no schistocytes is classic for immune thrombocytopenia, caused by autoantibodies against platelet glycoproteins leading to splenic destruction. First-line treatment is corticosteroids such as prednisone, with intravenous immunoglobulin for severe bleeding or when a rapid rise is needed. Thrombotic thrombocytopenic purpura presents with schistocytes, hemolytic anemia, neurologic symptoms, renal dysfunction, and fever. Disseminated intravascular coagulation shows abnormal PT and aPTT, low fibrinogen, and elevated D-dimer. Acute leukemia would show blasts or other cytopenias, and heparin-induced thrombocytopenia requires heparin exposure and typically causes thrombosis.', 'Medium', 103, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 65-year-old man is admitted with community-acquired pneumonia and is bedridden. He has no active bleeding, no history of heparin-induced thrombocytopenia, and normal renal function. What is the most appropriate venous thromboembolism prophylaxis?', '["No prophylaxis; early ambulation alone", "Aspirin 81 mg daily", "Graduated compression stockings alone", "Pharmacologic prophylaxis with low-molecular-weight heparin", "Therapeutic-dose unfractionated heparin infusion"]'::jsonb, 3, 'Acutely ill medical inpatients at risk for venous thromboembolism should receive pharmacologic prophylaxis with low-molecular-weight heparin or low-dose unfractionated heparin unless there is a high bleeding risk. Low-dose unfractionated heparin three times daily is an acceptable alternative, particularly in renal failure. Aspirin is not adequate prophylaxis for venous thromboembolism. Graduated compression stockings alone are inferior to pharmacologic prophylaxis and are used only when anticoagulation is contraindicated. No prophylaxis is inappropriate for a bedridden patient with pneumonia. Therapeutic-dose heparin is treatment, not prophylaxis, and increases bleeding risk without added benefit.', 'Easy', 104, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 45-year-old man is diagnosed with a first unprovoked proximal deep vein thrombosis. He has no cancer, no prior venous thromboembolism, and no bleeding risk factors. He is started on apixaban. What is the recommended minimum duration of anticoagulation, and what should be considered thereafter?', '["6 weeks, then stop anticoagulation permanently", "3 months, then stop anticoagulation permanently", "6 months, then stop anticoagulation permanently", "1 month, then switch to aspirin alone", "At least 3 months, then reassess for extended anticoagulation"]'::jsonb, 4, 'A first unprovoked proximal deep vein thrombosis requires at least 3 months of anticoagulation. Because the recurrence risk after unprovoked venous thromboembolism is high, extended or indefinite anticoagulation should be considered after reassessing bleeding risk and patient preference. Six weeks is too short for a proximal deep vein thrombosis. Stopping permanently at 3 months without considering extension misses the substantial recurrence risk. Provoked deep vein thrombosis, by contrast, is treated for 3 months and then stopped. Switching to aspirin alone is less effective than continued anticoagulation for preventing recurrence.', 'Medium', 105, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 30-year-old woman develops a left leg deep vein thrombosis 1 week after a 12-hour flight. She takes a combined oral contraceptive pill and has no other risk factors or family history of thrombosis. What is the most appropriate management?', '["Anticoagulate for 6 weeks and continue the oral contraceptive", "Anticoagulate indefinitely and continue the oral contraceptive", "Anticoagulate for 3 months and discontinue the oral contraceptive", "Anticoagulate for 3 months and continue the oral contraceptive", "No anticoagulation; treat with aspirin and compression stockings"]'::jsonb, 2, 'This is a provoked deep vein thrombosis with transient risk factors, namely prolonged immobility during the flight and estrogen exposure. Provoked venous thromboembolism requires 3 months of anticoagulation, and the estrogen-containing contraceptive should be discontinued to remove the provoking factor, with a non-estrogen method such as a copper intrauterine device offered instead. Six weeks is too short for a proximal deep vein thrombosis. Indefinite anticoagulation is reserved for unprovoked or recurrent thrombosis. Continuing the oral contraceptive maintains the thrombotic risk. Aspirin alone is inadequate treatment for acute deep vein thrombosis.', 'Medium', 106, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 72-year-old man presents with fatigue and easy bruising. Labs show hemoglobin 9.0 g/dL with MCV 108 fL, white cell count 3.0 × 10⁹/L, and platelets 85,000/µL. Peripheral smear shows hypogranular neutrophils and pseudo-Pelger-Huët cells. Bone marrow biopsy shows hypercellular marrow with dysplasia in all three lineages and 4% blasts. What is the most likely diagnosis?', '["Aplastic anemia", "Myelodysplastic syndrome", "Acute myeloid leukemia", "Vitamin B12 deficiency", "Myelofibrosis"]'::jsonb, 1, 'Cytopenias with dysplasia in multiple lineages, hypogranular neutrophils, pseudo-Pelger-Huët cells, and a hypercellular marrow with fewer than 20% blasts define myelodysplastic syndrome, a clonal stem cell disorder. Acute myeloid leukemia requires 20% or more blasts in blood or marrow. Aplastic anemia shows a hypocellular marrow without dysplasia. Vitamin B12 deficiency causes macrocytosis and hypersegmented neutrophils but not multilineage dysplasia with thrombocytopenia, and B12 and folate deficiency must be excluded before diagnosis. Myelofibrosis shows marrow fibrosis, tear-drop cells, and leukoerythroblastosis rather than this dysplastic picture.', 'Hard', 107, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 78-year-old woman with low-risk myelodysplastic syndrome with isolated deletion 5q is transfusion-dependent for anemia. She has no excess blasts and a normal karyotype apart from del(5q). Her erythropoietin level is elevated. What is the most appropriate treatment?', '["Lenalidomide", "Erythropoiesis-stimulating agent", "Azacitidine", "Allogeneic stem cell transplant", "High-dose corticosteroids"]'::jsonb, 0, 'Myelodysplastic syndrome with isolated deletion 5q responds to lenalidomide, which can achieve transfusion independence in the majority of patients and even cytogenetic remission. Monitoring is needed for neutropenia, thrombocytopenia, and thrombotic risk. An erythropoiesis-stimulating agent works best when the erythropoietin level is low and transfusion burden is low; here the erythropoietin level is elevated, predicting poor response. Azacitidine is used for higher-risk myelodysplastic syndrome. Allogeneic stem cell transplant is the only cure but carries high mortality and is reserved for higher-risk, fit patients. Corticosteroids are not effective therapy for myelodysplastic syndrome.', 'Hard', 108, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old man presents with headache, dizziness, facial plethora, and intense pruritus after hot showers. Examination shows splenomegaly. Hemoglobin is 19.5 g/dL, hematocrit 58%, white cell count 12,000/µL, platelets 550,000/µL. Erythropoietin level is low and JAK2 V617F mutation is positive. What is the most appropriate initial management?', '["Therapeutic phlebotomy alone with no other therapy", "Hydroxyurea alone without phlebotomy", "Warfarin anticoagulation", "Phlebotomy to hematocrit below 45% plus low-dose aspirin", "Splenectomy"]'::jsonb, 3, 'This is polycythemia vera: JAK2-positive erythrocytosis with a low erythropoietin level, splenomegaly, and aquagenic pruritus. Standard management is phlebotomy to maintain hematocrit below 45% to reduce thrombotic risk, plus low-dose aspirin unless there is a bleeding contraindication. Phlebotomy alone omits the benefit of aspirin in preventing thrombosis. Hydroxyurea is added for high-risk patients, such as those over 60 or with prior thrombosis, but is not the initial step here. Warfarin is not indicated without thrombosis. Splenectomy is not a treatment for polycythemia vera.', 'Medium', 109, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 65-year-old woman presents with burning pain and erythema of her fingers and toes, headaches, and transient visual changes. She had a transient ischemic attack 1 year ago. Platelet count is 950,000/µL, hemoglobin and white cell count are normal. JAK2 V617F is positive, and there is no iron deficiency, infection, or malignancy. Bone marrow shows increased megakaryocytes. What is the most appropriate management?', '["Observation alone with no treatment", "Plateletpheresis as the sole therapy", "Warfarin anticoagulation alone", "Low-dose aspirin alone", "Low-dose aspirin plus hydroxyurea"]'::jsonb, 4, 'This is essential thrombocythemia with microvascular symptoms such as erythromelalgia, and she is high risk because of her age over 60 and prior transient ischemic attack. High-risk essential thrombocythemia requires cytoreduction with hydroxyurea plus low-dose aspirin to prevent thrombosis. Hydroxyurea is the preferred cytoreductive agent, with anagrelide or interferon as alternatives, and low-dose aspirin controls microvascular symptoms. Observation alone leaves her at high risk of stroke or myocardial infarction. Plateletpheresis is reserved for acute emergencies with severe thrombocytosis. Warfarin alone does not address the platelet-driven thrombotic risk, and aspirin alone is insufficient for high-risk disease with prior thrombosis.', 'Hard', 110, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 50-year-old man with alcoholic cirrhosis presents with fatigue and easy bruising. Examination shows massive splenomegaly. Labs show hemoglobin 10.5 g/dL, white cell count 2.8 × 10⁹/L, platelets 65,000/µL. Bone marrow biopsy is normal. What is the most likely explanation for his cytopenias?', '["Aplastic anemia", "Myelodysplastic syndrome", "Hypersplenism secondary to portal hypertension", "Immune thrombocytopenia", "Acute leukemia"]'::jsonb, 2, 'Cirrhosis causes portal hypertension and splenomegaly, and the enlarged spleen sequesters and destroys blood cells, producing hypersplenism with pancytopenia despite a normal bone marrow. Management focuses on treating the underlying liver disease and portal hypertension, for example with nonselective beta-blockers or transjugular intrahepatic portosystemic shunt when indicated. Splenectomy is rarely performed because of operative and infection risk in cirrhosis. Aplastic anemia would show a hypocellular marrow without splenomegaly. Myelodysplastic syndrome causes dysplasia on marrow examination, which is absent here. Immune thrombocytopenia causes isolated thrombocytopenia, not pancytopenia with splenomegaly, and acute leukemia would show blasts.', 'Medium', 111, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 25-year-old man presents with fatigue, jaundice, and left upper quadrant discomfort. He has splenomegaly, hemoglobin 9.5 g/dL, an elevated reticulocyte count, elevated indirect bilirubin, and spherocytes on peripheral smear. Osmotic fragility is increased. Direct Coombs test is negative. What is the most appropriate definitive management?', '["Splenectomy after appropriate vaccinations", "Lifelong corticosteroids", "Splenectomy without vaccination", "Chronic red cell transfusion", "Bone marrow transplant"]'::jsonb, 0, 'This is hereditary spherocytosis, an autosomal dominant defect in red cell membrane proteins such as spectrin and ankyrin, causing spherocytes that are destroyed in the spleen. Splenectomy is definitive because it removes the site of hemolysis, and it must be preceded by vaccination against encapsulated organisms including pneumococcus, Haemophilus influenzae type b, and meningococcus because of the risk of overwhelming post-splenectomy infection. Corticosteroids treat autoimmune hemolysis, which has a positive Coombs test, not hereditary spherocytosis. Chronic transfusion is supportive only. Bone marrow transplant is not indicated.', 'Medium', 112, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 25-year-old man presents with a painless, rubbery left supraclavicular lymph node, drenching night sweats, and 8 kg weight loss over 2 months. Examination shows no other adenopathy. Chest radiograph shows mediastinal widening. What is the most appropriate next step in diagnosis?', '["Fine-needle aspiration of the lymph node", "Excisional lymph node biopsy", "Empiric antibiotics for 2 weeks and re-examination", "Observation for 4 weeks", "Serum lactate dehydrogenase level alone"]'::jsonb, 1, 'Painless supraclavicular adenopathy with B symptoms and mediastinal widening is highly suggestive of Hodgkin lymphoma. Excisional lymph node biopsy provides intact nodal architecture, which is required to identify Reed-Sternberg cells and establish the diagnosis and subtype, and staging then includes CT or PET-CT. Supraclavicular nodes are almost always pathologic and warrant prompt biopsy. Fine-needle aspiration yields too little tissue for lymphoma diagnosis. Empiric antibiotics or observation would delay diagnosis in a patient with clear red flags. Lactate dehydrogenase is a nonspecific marker and cannot establish a diagnosis.', 'Medium', 113, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 60-year-old man has a hard, fixed, nontender 3 cm cervical lymph node that has persisted for 6 weeks. He has a 40 pack-year smoking history and drinks alcohol heavily. He has no fever or recent infection. What is the most appropriate next step?', '["Reassure and re-examine in 3 months", "Start amoxicillin-clavulanate for 10 days", "Fine-needle aspiration only", "Excisional biopsy of the lymph node", "Order a chest radiograph and observe"]'::jsonb, 3, 'A hard, fixed, painless lymph node larger than 2 cm persisting for more than 4 to 6 weeks in an older smoker is concerning for metastatic squamous cell carcinoma from a head and neck primary, and excisional biopsy provides tissue for definitive diagnosis. Reassurance and observation risk missing a malignancy. Antibiotics are for infectious adenopathy, which is typically tender and febrile. Fine-needle aspiration alone may be insufficient when lymphoma or metastatic carcinoma is suspected and architecture is needed. A chest radiograph alone does not establish the diagnosis.', 'Medium', 114, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 55-year-old woman receiving chemotherapy for breast cancer presents with a temperature of 39.2°C, chills, and malaise. Her absolute neutrophil count is 300/µL. She has no localizing symptoms. Blood pressure is 110/70 mm Hg. What is the most appropriate immediate management?', '["Outpatient oral amoxicillin and close follow-up", "Wait for blood culture results before starting antibiotics", "Give oral ciprofloxacin alone", "Administer granulocyte colony-stimulating factor alone and observe", "Obtain blood cultures and start empiric intravenous cefepime"]'::jsonb, 4, 'Febrile neutropenia, defined as fever of 38.3°C or higher with an absolute neutrophil count below 500/µL, is a medical emergency. Blood cultures should be obtained and broad-spectrum intravenous antipseudomonal antibiotics such as cefepime started immediately, without waiting for culture results, because delayed antibiotics increase mortality. If the patient is hypotensive or has a suspected central line infection, vancomycin is added, and antifungal therapy is considered if fever persists beyond 4 to 7 days. Outpatient oral therapy is only for carefully selected low-risk patients. Oral ciprofloxacin alone provides inadequate coverage, and granulocyte colony-stimulating factor is an adjunct, not a substitute for antibiotics.', 'Medium', 115, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 40-year-old woman with schizophrenia on clozapine for 6 months presents with fever, sore throat, and mouth ulcers. Her absolute neutrophil count is 100/µL. What is the most appropriate immediate management?', '["Continue clozapine and add prophylactic antibiotics", "Reduce the clozapine dose by half and monitor the ANC", "Discontinue clozapine immediately and start broad-spectrum antibiotics", "Switch clozapine to olanzapine and continue treatment", "Give granulocyte colony-stimulating factor and continue clozapine"]'::jsonb, 2, 'Clozapine-induced agranulocytosis, an absolute neutrophil count below 500/µL, requires immediate discontinuation of clozapine, which must not be rechallenged, plus treatment as febrile neutropenia with broad-spectrum antibiotics. The absolute neutrophil count must be monitored until recovery, and the patient should be counselled never to receive clozapine again, since fever in a patient on clozapine should always prompt an urgent ANC check. Continuing clozapine or merely reducing the dose perpetuates marrow suppression and risks fatal infection. Switching to another antipsychotic can be considered only after the neutrophil count recovers. Granulocyte colony-stimulating factor may be used as an adjunct but does not replace stopping the offending drug.', 'Hard', 116, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 30-year-old man presents with his second unprovoked proximal deep vein thrombosis in 2 years. His father had a pulmonary embolism at age 45. Testing reveals heterozygosity for factor V Leiden. What is the most appropriate long-term management?', '["Indefinite anticoagulation", "Anticoagulation for 3 months, then stop", "Anticoagulation for 6 weeks, then stop", "Aspirin alone indefinitely", "No anticoagulation; compression stockings only"]'::jsonb, 0, 'Recurrent unprovoked venous thromboembolism, particularly with an inherited thrombophilia such as factor V Leiden, warrants indefinite anticoagulation after weighing bleeding risk, because the recurrence risk is high. The presence of heterozygous factor V Leiden increases risk but does not by itself mandate indefinite therapy after a single provoked event; recurrence is the key driver here. Three months of anticoagulation is adequate for a single provoked event but not for recurrence. Six weeks is too short even for a first proximal thrombosis. Aspirin alone is less effective than continued anticoagulation for preventing recurrence, and compression stockings prevent post-thrombotic syndrome but do not prevent recurrent thrombosis.', 'Medium', 117, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 35-year-old woman develops a deep vein thrombosis 2 weeks after starting a combined oral contraceptive pill. Workup reveals heterozygosity for the prothrombin G20210A mutation. She has no other risk factors. What is the most appropriate management?', '["Anticoagulate indefinitely and continue the oral contraceptive", "Anticoagulate for 3 months and discontinue the oral contraceptive", "Anticoagulate for 3 months and continue the oral contraceptive", "No anticoagulation; switch to a progestin-only pill", "Anticoagulate for 6 weeks and continue the oral contraceptive"]'::jsonb, 1, 'This is a provoked deep vein thrombosis with a transient risk factor, namely estrogen exposure, in a patient with prothrombin G20210A mutation. Provoked venous thromboembolism requires 3 months of anticoagulation, and the estrogen-containing contraceptive must be discontinued and replaced with a non-estrogen method such as a copper intrauterine device or progestin-only pill. Indefinite anticoagulation is reserved for unprovoked or recurrent thrombosis. Continuing the oral contraceptive maintains the thrombotic risk. Thrombophilia testing does not usually change management after a provoked event, although family screening may be discussed. Anticoagulation is required; no treatment or aspirin alone is inadequate for acute deep vein thrombosis.', 'Medium', 118, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 70-year-old man with coronary artery disease is admitted with melena. He is hemodynamically stable, heart rate 92/min, blood pressure 118/72 mm Hg. Hemoglobin is 6.8 g/dL. He has no chest pain. What is the most appropriate transfusion decision?', '["No transfusion; give intravenous iron alone", "Transfuse to a hemoglobin target above 10 g/dL", "Give erythropoietin and recheck hemoglobin in 24 hours", "Transfuse one unit of packed red blood cells and reassess", "Transfuse platelets before any red cells"]'::jsonb, 3, 'A restrictive transfusion strategy uses a hemoglobin threshold of 7 g/dL in stable patients, including those with cardiovascular disease, where a threshold of 7 to 8 g/dL is used. At 6.8 g/dL he meets the threshold, so one unit of packed red blood cells should be transfused and the patient reassessed, rather than transfusing multiple units at once. Intravenous iron and erythropoietin act too slowly for acute anemia. A liberal target above 10 g/dL increases transfusion risks without benefit. Platelets are not indicated without thrombocytopenia or platelet dysfunction.', 'Medium', 119, 'MCQ'),
('c2df3785-8a9b-4f1d-90ca-514eac8cdf4d', 'A 45-year-old man with acute myeloid leukemia undergoing induction chemotherapy has a platelet count of 8,000/µL. He has no active bleeding, no fever, and is hemodynamically stable. What is the most appropriate management?', '["No transfusion; observe until bleeding occurs", "Give desmopressin to improve platelet function", "Transfuse platelets only if the count falls below 5,000/µL", "Start high-dose corticosteroids", "Give a prophylactic platelet transfusion"]'::jsonb, 4, 'The prophylactic platelet transfusion threshold is below 10,000/µL in stable patients without bleeding, and higher, below 20,000/µL, with fever, sepsis, or an invasive procedure, and below 50,000/µL before most surgery or lumbar puncture. At 8,000/µL he should receive a prophylactic platelet transfusion. Waiting for bleeding risks catastrophic hemorrhage. Platelet refractoriness from alloimmunization is managed with HLA-matched or crossmatched platelets. Desmopressin improves platelet function in uremia or von Willebrand disease, not thrombocytopenia from chemotherapy. A threshold of 5,000/µL is too low, and corticosteroids treat immune thrombocytopenia, not chemotherapy-induced marrow suppression.', 'Easy', 120, 'MCQ');
